export const COPING_WITH_STRESS_ACTIVITIES = [
{n:1,type:"mcq",micro:"Apa itu stres",q:"'Stres' adalah...",options:["Respons tubuh & pikiran terhadap tuntutan atau tekanan, saat kita merasa yang diminta melebihi yang bisa kita tangani saat itu","Sesuatu yang hanya dialami orang dewasa yang bekerja, sehingga anak-anak & remaja jarang merasakannya","Tanda bahwa seseorang lemah & tidak mampu menghadapi hidup, sehingga orang yang kuat tidak akan pernah merasakan stres sedikit pun"],answer:0,explain:"Stres adalah pengalaman manusiawi & normal. Semua orang mengalaminya. Yang penting adalah bagaimana kita mengelolanya.",hint:"Respons terhadap tuntutan/tekanan, atau tanda kelemahan?"},
{n:2,type:"mcq",micro:"Respons stres tubuh",q:"Saat menghadapi sesuatu yang menekan, tubuh sering bereaksi dengan...",options:["Tubuh langsung tertidur nyenyak karena terlalu lelah menghadapi tekanan itu, sehingga kita tidak merasakan apa-apa lagi","Jantung berdetak lebih cepat, napas lebih pendek, otot menegang, perut terasa tidak enak, ini respons alami 'siaga'","Tidak ada reaksi fisik di tubuh, karena stres hanya terjadi di pikiran dan tak memengaruhi tubuh kita"],answer:1,explain:"Respons ini (kadang disebut 'lawan-lari-diam') menyiapkan tubuh menghadapi ancaman. Berguna untuk bahaya nyata, kurang cocok untuk ujian atau presentasi.",hint:"Reaksi 'siaga' tubuh, atau tak ada reaksi / langsung tidur?"},
{n:3,type:"mcq",micro:"Stres bisa positif atau negatif",q:"Tidak semua stres buruk. Stres dalam jumlah wajar bisa...",options:["Merugikan dalam bentuk dan jumlah berapa pun, sehingga kita harus berusaha menghilangkannya dari kehidupan","Berarti kita tidak peduli pada hal apa saja, sebab orang yang peduli terus tertekan dan tak bisa tampil terbaik","Membantu kita fokus, bersiap, & tampil lebih baik (mis. sedikit gugup sebelum lomba yang membuat lebih waspada)"],answer:2,explain:"Stres ringan bisa jadi 'bahan bakar'. Yang bermasalah adalah stres yang terlalu besar atau berlangsung terlalu lama tanpa jeda.",hint:"Bisa membantu fokus & bersiap, atau selalu merugikan?"},
{n:4,type:"mcq",micro:"Stres yang berlebihan",q:"Stres jadi bermasalah ketika...",options:["Terlalu besar atau berlangsung terus-menerus tanpa jeda, sehingga mengganggu tidur, konsentrasi, suasana hati, atau kesehatan","Muncul sesekali saja menjelang hal penting & hilang lagi setelah hal itu selesai, serta tidak mengganggu kegiatan sehari-hari kita","Kita merasa sedikit gugup sebelum tampil atau ujian, lalu perasaan itu berlalu begitu saja tanpa memengaruhi tidur atau kesehatan kita"],answer:0,explain:"Stres akut sesekali adalah bagian hidup. Stres yang menetap & mengganggu fungsi sehari-hari adalah yang perlu perhatian & penanganan lebih.",hint:"Terlalu besar/terus-menerus & mengganggu fungsi, atau sesekali menjelang hal penting?"},
{n:5,type:"mcq",micro:"Tanda stres: fisik",q:"Tanda stres di tubuh bisa berupa...",options:["Tidak ada tanda fisik, karena stres hanya terasa di pikiran dan perasaan","Sakit kepala, sakit perut, otot tegang, sulit tidur, mudah lelah, jantung berdebar","Merasa sehat & berenergi sepanjang hari, tak mengantuk atau lelah, serta tak mengalami sakit"],answer:1,explain:"Tubuh sering 'menyimpan' stres. Menyadari tanda-tanda fisik ini membantu kita mengenali saat sedang tertekan sebelum menumpuk lebih jauh.",hint:"Sakit kepala/perut, otot tegang, sulit tidur, atau selalu sehat berenergi?"},
{n:6,type:"mcq",micro:"Tanda stres: emosi & pikiran",q:"Tanda stres di emosi & pikiran bisa berupa...",options:["Merasa tenang, jernih, & mudah berkonsentrasi, serta mampu menyelesaikan pekerjaan dengan santai tanpa menghindar","Tidak berpikir apa-apa, sebab pikiran jadi kosong dan sunyi setiap kali merasa tertekan","Mudah kesal/cemas, sulit fokus, pikiran berputar-putar, merasa kewalahan, atau menghindari hal-hal"],answer:2,explain:"Stres memengaruhi cara kita merasa & berpikir. Sulit berkonsentrasi & mudah tersinggung sering merupakan sinyal stres yang tinggi.",hint:"Mudah kesal, sulit fokus, kewalahan, atau selalu tenang & jernih?"},
{n:7,type:"mcq",micro:"Tanda stres: perilaku",q:"Tanda stres di perilaku bisa berupa...",options:["Menunda-nunda, menarik diri dari teman, perubahan pola makan/tidur, atau lebih banyak marah/menangis dari biasanya","Menjadi lebih rajin & terorganisir dari biasanya, serta tidak menunda pekerjaan atau menarik diri dari orang lain","Tidak ada perubahan perilaku, karena stres hanya tersimpan dalam hati & tak terlihat dari cara bertindak"],answer:0,explain:"Perubahan pola perilaku yang tiba-tiba (jadi lebih menyendiri, menunda, atau berubah pola makan/tidur) bisa jadi cara stres muncul.",hint:"Menunda, menarik diri, perubahan pola, atau lebih rajin & terorganisir?"},
{n:8,type:"mcq",micro:"Mengenali stres pada diri sendiri",q:"Menyadari 'aku sedang stres' (bukan hanya 'aku benci semuanya') berguna karena...",options:["Membuat stres jadi lebih buruk, karena makin kita menyadari dan menyebutkannya, makin besar tekanan yang terasa","Kita bisa mulai menangani sumbernya & merawat diri, bukan sekadar terbawa perasaan buruk tanpa tahu sebabnya","Tidak ada gunanya menyadari, sebab stres hilang sendiri dan mengetahui namanya tak mengubah perasaan kita"],answer:1,explain:"Menamai 'ini stres' adalah langkah pertama untuk merespons secara sadar, bukan sekadar bereaksi.",hint:"Bisa mulai menangani & merawat diri, atau tak berguna / memperburuk?"},
{n:9,type:"order",micro:"Langkah awal menghadapi stres",q:"Urutkan langkah awal saat menyadari sedang stres.",items:["Sadari & namai: 'aku sedang stres, tubuhku bereaksi, pikiranku berputar'","Tenangkan tubuh sedikit (napas perlahan, jeda sebentar) agar bisa berpikir lebih jernih","Cari tahu: apa sumber utama stres ini? apa yang paling membebani?","Pilih langkah: apa yang bisa kulakukan tentang sumbernya, & apa yang bisa membantu perasaanku sekarang"],answer:[0,1,2,3],explain:"Sadari → tenangkan tubuh → cari sumbernya → pilih langkah. Berpikir jernih tentang solusi datang setelah tubuh sedikit tenang.",hint:"Mencari sumber stres dilakukan sebelum atau sesudah menenangkan tubuh sedikit?"},
{n:10,type:"mcq",micro:"Stres bisa dikelola",q:"Menghadapi stres yang sehat berarti...",options:["Berusaha agar tidak merasakan stres dalam hidup, dengan menghindari tantangan, tugas, dan hal baru yang menekan","Mengabaikan stres & memaksakan diri terus bekerja tanpa berhenti, karena mengakui stres membuat kita terlihat lemah dan tertinggal","Belajar mengenali, menenangkan diri, menangani sumbernya sebisa mungkin, & tahu kapan mencari bantuan, bukan berusaha tidak pernah stres"],answer:2,explain:"Tujuannya bukan hidup tanpa stres (yang tidak realistis), tapi punya cara-cara sehat untuk menghadapinya.",hint:"Mengenali, menenangkan, menangani, & tahu batas, atau tak pernah stres / mengabaikan?"},
{n:11,type:"tf",micro:"Semua orang mengalami stres",q:"Benar atau Salah: Setiap orang mengalami stres kadang-kadang; merasakannya bukan tanda bahwa ada yang salah dengan diri kita.",answer:true,explain:"Stres adalah respons manusiawi terhadap tuntutan hidup. Yang berbeda antar orang adalah cara mereka mengelolanya, & itu bisa dilatih.",hint:"Semua orang mengalaminya, atau tanda ada yang salah?"},
{n:12,type:"tf",micro:"Stres selalu tanda harus menyerah?",q:"Benar atau Salah: Merasa stres tentang sesuatu berarti kita harus langsung menyerah & meninggalkan hal itu.",answer:false,explain:"Sebaliknya, stres sering muncul justru karena sesuatu penting bagi kita. Yang dibutuhkan biasanya bukan menyerah, tapi menemukan cara mengelola & menangani tantangannya.",hint:"Harus langsung menyerah, atau cari cara mengelola & menangani?"},
{n:13,type:"mcq",micro:"Stres akut vs kronis",q:"Beda 'stres akut' (sesaat) dengan 'stres kronis' (berkepanjangan):",options:["Akut: menjelang ujian lalu mereda setelahnya. Kronis: tekanan yang terus-menerus selama berminggu-minggu/berbulan-bulan tanpa jeda yang cukup","Keduanya sama saja, hanya beda istilah untuk menyebut tekanan yang dialami seseorang dalam hidupnya","Stres akut lebih berbahaya daripada stres kronis, karena datang tiba-tiba dan langsung merusak tubuh serta pikiran seseorang"],answer:0,explain:"Stres kronis lebih berisiko bagi kesehatan fisik & mental karena tubuh tidak pernah benar-benar 'pulih' dari mode siaga. Ini yang paling penting untuk mendapat perhatian & bantuan.",hint:"Sesaat vs berkepanjangan tanpa jeda, atau sama saja?"},
{n:14,type:"mcq",micro:"Stres & jeda pemulihan",q:"Kenapa jeda pemulihan (istirahat, waktu tenang, tidur) penting saat menghadapi periode menekan?",options:["Semakin sedikit istirahat, semakin kuat kita menghadapi stres, sebab tubuh yang terbiasa bekerja tanpa jeda akan menjadi semakin tahan terhadap tekanan","Tubuh & pikiran butuh waktu 'turun' dari mode siaga untuk memulihkan energi; tanpa jeda, stres menumpuk & kita jadi lebih rentan kewalahan","Jeda hanya membuang waktu produktif yang seharusnya dipakai menyelesaikan pekerjaan, jadi lebih baik tidak beristirahat sampai semua tugas selesai"],answer:1,explain:"Menghadapi tekanan terus-menerus tanpa jeda seperti menyalakan mesin tanpa henti, akhirnya kelelahan. Jeda adalah bagian dari mengelola stres, bukan kemalasan.",hint:"Tubuh butuh waktu memulihkan diri, atau jeda membuang waktu?"},
{n:15,type:"mcq",micro:"Menenangkan tubuh saat stres",q:"Teknik cepat yang bisa membantu menurunkan respons stres tubuh:",options:["Menahan napas selama mungkin sampai wajah terasa panas, lalu menghembuskannya sekaligus untuk membuang ketegangan","Bernapas cepat & pendek beberapa menit sampai tubuh penuh tenaga dan ketegangan hilang","Menarik napas perlahan & dalam beberapa kali, dengan hembusan lebih panjang dari tarikan"],answer:2,explain:"Napas yang lambat & dalam memberi sinyal 'aman' pada tubuh, membantu menurunkan detak jantung & ketegangan.",hint:"Napas perlahan & dalam, atau menahan / secepat mungkin?"},
{n:16,type:"tf",micro:"Menghadapi stres bisa dilatih",q:"Benar atau Salah: Kemampuan menghadapi stres dengan sehat adalah bakat tetap sejak lahir yang tidak bisa dilatih atau dikembangkan.",answer:false,explain:"Sebaliknya, ini keterampilan: seperti keterampilan lain, semakin sering kita berlatih mengenali & mengelola stres, semakin baik & alami kemampuan itu.",hint:"Bisa dilatih & berkembang, atau bakat tetap?"},
{n:17,type:"mcq",micro:"Stres & aktivitas fisik",q:"Bergerak/berolahraga saat stres bisa membantu karena...",options:["Membantu 'membakar' energi berlebih dari respons stres & sering memperbaiki suasana hati serta membuat pikiran lebih jernih setelahnya","Membuat stres jadi lebih buruk, karena tubuh yang bergerak makin lelah & pikiran makin sulit dikendalikan setelah itu","Tidak berhubungan dengan stres, sebab gerak badan hanya memengaruhi otot dan tidak memengaruhi suasana hati"],answer:0,explain:"Respons stres menyiapkan tubuh untuk 'lawan-lari'. Bergerak memberi jalan keluar yang sehat untuk energi itu.",hint:"Membakar energi & perbaiki suasana hati, atau memperburuk / tak berhubungan?"},
{n:18,type:"mcq",micro:"Berbicara tentang stres",q:"Menceritakan apa yang membuat kita stres ke orang tepercaya bisa membantu karena...",options:["Membuat stres menyebar ke orang lain & bertambah besar, sehingga masalah kita justru lebih berat setelah diceritakan","Berbicara sering membuat masalah terasa lebih jelas & lebih bisa ditangani, & merasa didengar mengurangi beratnya","Membebani orang lain dengan masalah kita, sehingga lebih baik disimpan sendiri agar tidak mengganggu perasaan mereka"],answer:1,explain:"Kita tidak harus menghadapi stres sendirian. Berbagi dengan orang yang tepat adalah salah satu cara paling efektif meringankannya.",hint:"Membuat lebih jelas & terasa lebih ringan, atau membebani / memperberat?"},
{n:19,type:"mcq",micro:"Sumber stres yang umum bagi pelajar",q:"Hal-hal yang umum menjadi sumber stres bagi anak & remaja:",options:["Hanya ujian & nilai di sekolah, tidak ada hal lain yang bisa membuat anak & remaja merasa tertekan dalam kehidupan sehari-harinya sekalipun","Anak & remaja tidak mengalami stres karena belum punya tanggung jawab besar, sehingga stres hanya masalah orang dewasa","Tuntutan akademik (ujian, tugas, nilai), masalah sosial (pertemanan, perundungan), tekanan keluarga, perubahan besar, & membandingkan diri dengan orang lain"],answer:2,explain:"Mengenali berbagai sumber stres membantu kita memahami apa yang sedang kita hadapi & mencari bantuan yang tepat.",hint:"Berbagai sumber (akademik, sosial, keluarga, perbandingan), atau hanya ujian / tidak ada?"},
{n:20,type:"open",micro:"Petakan stresmu",q:"Refleksikan periode belakangan ini. Tulis: (a) 3 tanda bahwa kamu sedang stres (bisa fisik, emosi, pikiran, atau perilaku), (b) 2-3 sumber utama stresmu saat ini, (c) untuk masing-masing sumber, apakah itu sesuatu yang bisa kamu kendalikan/pengaruhi, atau di luar kendalimu, (d) satu hal kecil yang sudah kamu lakukan (atau bisa mulai lakukan) untuk merawat diri di tengah stres ini.",explain:"Jawaban baik: 3 tanda stres yang spesifik & mencakup berbagai jenis (fisik, pikiran, perilaku), 2-3 sumber yang jelas, analisis yang jujur tentang apa yang bisa & tidak bisa dikendalikan untuk masing-masing (menunjukkan pemahaman bahwa keduanya butuh pendekatan berbeda), & satu langkah perawatan diri yang konkret & kecil.",hint:"Untuk (c), bedakan: apa yang bisa kamu LAKUKAN tentang sumber itu, vs apa yang harus kamu TERIMA & kelola perasaanmu tentangnya.",sample:"(a) Tanda-tanda stres: (1) Fisik, aku sering sakit kepala di sore hari & bahuku terasa tegang. (2) Pikiran, aku sulit fokus saat belajar, pikiranku melompat-lompat ke banyak hal yang harus dikerjakan. (3) Perilaku, aku jadi lebih sering menunda-nunda & kadang mudah marah pada adikku untuk hal kecil. (b) Sumber utama stres: (1) Ujian akhir semester yang tinggal 3 minggu lagi & aku merasa belum siap di beberapa mata pelajaran. (2) Ketegangan dengan sekelompok teman yang belakangan menjauhiku tanpa jelas alasannya. (3) Orang tuaku sering menanyakan nilai & aku takut mengecewakan mereka. (c) Bisa dikendalikan atau tidak: Ujian, sebagian bisa kupengaruhi, aku bisa membuat jadwal belajar & meminta bantuan guru untuk materi yang sulit, meski aku tidak bisa mengontrol soal yang keluar. Teman yang menjauh, aku bisa mencoba bertanya baik-baik apa yang terjadi, tapi aku tidak bisa memaksa mereka berteman lagi, sebagian di luar kendaliku. Tekanan orang tua, aku bisa mencoba bicara dengan mereka tentang bagaimana perasaanku, tapi aku tidak bisa mengubah harapan mereka sepenuhnya. (d) Yang sudah/akan kulakukan untuk merawat diri: aku mulai jalan kaki 15 menit setiap sore setelah belajar, & itu membantu kepalaku terasa lebih ringan; aku juga mulai menulis daftar tugas di malam hari supaya pikiranku tidak berputar saat mau tidur."},
{n:21,type:"classify",micro:"Cara sehat vs kurang sehat menghadapi stres",q:"Kelompokkan tiap cara ke 'Sehat' atau 'Kurang sehat' menghadapi stres.",items:["Memecah tugas besar jadi langkah-langkah kecil & mengerjakan satu per satu","Menghindari semua tugas & berharap masalahnya hilang sendiri","Berbicara dengan orang tepercaya tentang apa yang membebani","Melampiaskan stres dengan marah pada orang lain yang tidak bersalah"],groups:["Sehat","Kurang sehat"],answer:{"Sehat":["Memecah tugas besar jadi langkah-langkah kecil & mengerjakan satu per satu","Berbicara dengan orang tepercaya tentang apa yang membebani"],"Kurang sehat":["Menghindari semua tugas & berharap masalahnya hilang sendiri","Melampiaskan stres dengan marah pada orang lain yang tidak bersalah"]},explain:"Sehat: mengambil langkah pada masalah, mencari dukungan. Kurang sehat: menghindar total, melampiaskan ke orang lain.",hint:"Mengambil langkah & mencari dukungan, atau menghindar / melampiaskan?"},
{n:22,type:"mcq",micro:"Apa yang bisa & tidak bisa dikendalikan",q:"Salah satu langkah paling berguna menghadapi stres adalah membedakan...",options:["Hal yang bisa kamu pengaruhi/kendalikan (usahamu, rencanamu, cara meresponsmu) dari yang di luar kendalimu (hasil akhir, tindakan orang lain, keadaan tertentu)","Semua hal bisa kamu kendalikan kalau berusaha cukup keras, sehingga tak perlu membedakan mana yang bisa & tidak bisa kamu atur dalam hidupmu","Tidak ada hal yang bisa kamu kendalikan dalam hidup ini, sehingga lebih baik pasrah dan tak perlu berusaha"],answer:0,explain:"Untuk yang bisa dikendalikan: buat rencana & bertindak. Untuk yang tidak: fokus mengelola perasaanmu & menerima ketidakpastiannya. Mencampurnya menambah stres.",hint:"Membedakan yang bisa & tidak bisa dikendalikan, atau anggap semua bisa / tidak ada?"},
{n:23,type:"mcq",micro:"Stres akademik",q:"Menghadapi stres soal pelajaran/ujian, langkah yang mengurangi rasa kewalahan:",options:["Menghindari belajar sampai menit terakhir menjelang ujian, lalu mengerjakan semuanya sekaligus dalam semalam supaya tidak terlalu lama memikirkannya","Buat daftar apa yang perlu dipelajari, pecah jadi bagian kecil, jadwalkan dengan realistis, & minta bantuan untuk yang sulit","Memikirkan semua materi sekaligus sebagai satu kesatuan besar tanpa membaginya, supaya kita bisa melihat seberapa banyak yang harus diselesaikan"],answer:1,explain:"'Gunung' tugas terasa lebih kecil saat dipecah jadi 'langkah-langkah'. Rencana yang jelas mengurangi kecemasan 'aku tidak akan sanggup'.",hint:"Pecah & jadwalkan realistis, atau pikirkan semua sekaligus / hindari?"},
{n:24,type:"mcq",micro:"Stres sosial",q:"Menghadapi stres soal pertemanan (konflik, merasa dikucilkan), langkah yang membantu:",options:["Memendam semuanya & menganalisis masalah sendirian berulang-ulang di dalam kepala, tanpa bicara atau mengambil tindakan","Membalas dengan mengucilkan mereka juga, supaya mereka merasakan hal yang sama & tahu betapa tidak enaknya diperlakukan seperti itu oleh teman","Bicara langsung & baik-baik dengan yang terlibat bila memungkinkan, cari dukungan dari teman/keluarga lain, & ingat bahwa dinamika pertemanan bisa berubah"],answer:2,explain:"Stres sosial sering butuh komunikasi & dukungan dari luar situasi itu. Memendam sendiri sering memperbesar kecemasan.",hint:"Bicara + cari dukungan lain, atau memendam / membalas?"},
{n:25,type:"mcq",micro:"Stres dari perbandingan",q:"Membandingkan diri terus-menerus dengan orang lain (nilai, penampilan, pencapaian) sering menambah stres karena...",options:["Kita membandingkan kesulitan kita sendiri dengan 'versi terbaik' yang ditampilkan orang lain, & selalu ada yang terlihat 'lebih' dalam hal apa pun","Perbandingan memotivasi kita menjadi lebih baik & tidak merugikan perasaan, sehingga sebaiknya kita sering membandingkan diri dengan orang lain","Tidak ada hubungan antara membandingkan diri dengan orang lain & stres, sebab stres hanya datang dari tugas dan tuntutan nyata, bukan dari pikiran kita"],answer:0,explain:"Perbandingan yang tidak sehat adalah 'pertarungan yang tidak bisa dimenangkan'. Fokus pada kemajuan & tujuan kita sendiri lebih membantu.",hint:"Membandingkan dengan 'versi terbaik' orang lain, atau selalu memotivasi / tak berhubungan?"},
{n:26,type:"mcq",micro:"Stres dari perubahan",q:"Perubahan besar (pindah rumah/sekolah, perubahan keluarga, memasuki jenjang baru) sering menimbulkan stres karena...",options:["Berarti kita tidak fleksibel & tak mampu beradaptasi, sehingga hanya orang lemah yang tertekan saat menghadapi perubahan besar","Kita kehilangan hal yang familiar & harus menyesuaikan diri dengan yang baru, yang membutuhkan energi & waktu","Perubahan besar tidak menimbulkan stres pada orang mana pun, karena orang menyesuaikan diri dalam waktu singkat"],answer:1,explain:"Stres saat perubahan adalah hal yang wajar & sementara. Memberi diri waktu & kesabaran untuk menyesuaikan diri itu penting.",hint:"Kehilangan yang familiar & butuh menyesuaikan diri, atau tak menimbulkan stres / berarti tak fleksibel?"},
{n:27,type:"tf",micro:"Stres kronis butuh perhatian lebih",q:"Benar atau Salah: Stres yang berlangsung terus-menerus selama berminggu-minggu atau berbulan-bulan, tanpa jeda yang cukup & mengganggu banyak aspek hidup, adalah tanda untuk mencari dukungan lebih (orang dewasa tepercaya, konselor, profesional).",answer:true,explain:"Stres kronis lebih berisiko bagi kesehatan & sering terlalu berat untuk ditangani sendirian. Mencari bantuan untuk stres seperti ini adalah langkah bijak.",hint:"Butuh dukungan lebih, atau harus ditanggung sendiri?"},
{n:28,type:"tf",micro:"Menghindar total memperbesar stres",q:"Benar atau Salah: Menghindari sepenuhnya sesuatu yang membuat stres (mis. terus menunda tugas, tidak pernah membahas konflik) biasanya membuat stres berkurang untuk selamanya.",answer:false,explain:"Sebaliknya, penghindaran total sering memberi kelegaan sesaat tapi membuat masalah menumpuk & stres kembali lebih besar. Menghadapi bertahap (dengan dukungan bila perlu) lebih efektif jangka panjang.",hint:"Membuat stres berkurang selamanya, atau kelegaan sesaat tapi menumpuk?"},
{n:29,type:"mcq",micro:"Stres & harapan yang tidak realistis",q:"Menuntut diri sendiri sempurna dalam segala hal (perfeksionisme) sering menambah stres karena...",options:["Perfeksionisme menghasilkan yang terbaik tanpa biaya, sehingga makin tinggi kita menuntut diri, makin tenang dan puas perasaan kita","Tidak ada hubungan antara standar yang kita pasang & stres","Standar 'sempurna' hampir tidak mungkin dipenuhi terus-menerus, jadi kita selalu merasa kurang & cemas"],answer:2,explain:"Menetapkan standar 'cukup baik' & realistis untuk sebagian besar hal (menyimpan usaha ekstra untuk yang benar-benar penting) mengurangi stres yang tidak perlu.",hint:"Standar mustahil bikin selalu cemas, atau selalu menghasilkan terbaik / tak berhubungan?"},
{n:30,type:"order",micro:"Menangani sumber stres yang bisa dikendalikan",q:"Urutkan langkah menangani sumber stres yang bisa kamu pengaruhi (mis. tugas menumpuk).",items:["Tuliskan dengan jelas apa saja yang membebani (keluarkan dari kepala ke kertas)","Pisahkan mana yang bisa kamu pengaruhi & mana yang tidak","Untuk yang bisa dipengaruhi: pecah jadi langkah kecil & jadwalkan","Mulai dari satu langkah kecil, & minta bantuan untuk bagian yang di luar kemampuanmu"],answer:[0,1,2,3],explain:"Tulis semua → pisahkan yang bisa/tidak bisa → pecah & jadwalkan yang bisa → mulai kecil & minta bantuan. Menuliskan mengurangi beban 'semua di kepala'.",hint:"Memisahkan yang bisa/tidak bisa dikendalikan dilakukan sebelum atau sesudah memecah jadi langkah kecil?"},
{n:31,type:"mcq",micro:"Stres yang menumpuk dari banyak hal kecil",q:"Kadang stres besar sebenarnya banyak hal kecil yang menumpuk (kurang tidur + tugas + konflik + lapar). Menyadari ini membantu kita...",options:["Menangani beberapa hal kecil (merawat kebutuhan dasar, menyelesaikan satu tugas) untuk mengurangi 'beban total', alih-alih merasa kewalahan oleh 'satu masalah besar'","Menyerah saja karena masalahnya terlalu banyak untuk diselesaikan, lalu menunggu sampai semuanya mereda sendiri tanpa melakukan apa-apa","Fokus hanya pada satu hal yang paling besar dan mengabaikan semua hal kecil lainnya, karena hal kecil tidak ada hubungannya dengan beban kita"],answer:0,explain:"'Wadah stres' yang hampir penuh bisa dikurangi dengan mengeluarkan beberapa hal kecil, tidak harus menyelesaikan semuanya sekaligus.",hint:"Kurangi beberapa hal kecil, atau menyerah / abaikan sisanya?"},
{n:32,type:"tf",micro:"Kebutuhan dasar sebagai penyangga stres",q:"Benar atau Salah: Merawat kebutuhan dasar (tidur cukup, makan teratur, bergerak, dukungan sosial) membuat kita lebih tahan menghadapi stres, ini seperti 'penyangga' yang membantu kita tidak mudah kewalahan.",answer:true,explain:"Fondasi yang terawat memberi 'cadangan' untuk menghadapi tekanan. Mengorbankan kebutuhan dasar saat stres tinggi sering justru memperburuk kemampuan menghadapinya.",hint:"Membuat lebih tahan menghadapi stres, atau tak berpengaruh?"},
{n:33,type:"mcq",micro:"Dua jenis strategi menghadapi stres",q:"Dua pendekatan umum menghadapi stres:",options:["Tidak ada strategi untuk stres, sehingga yang bisa dilakukan hanyalah menahannya sampai tekanan itu hilang sendiri dengan berjalannya waktu","'Berfokus pada masalah' (mengubah/menangani sumbernya) & 'berfokus pada emosi' (mengelola perasaan tentangnya); keduanya berguna sesuai situasi","Hanya ada satu cara yang benar untuk semua situasi & orang, jadi kita tak perlu menyesuaikan strategi dengan masalah"],answer:1,explain:"Untuk stres yang bisa kita pengaruhi: fokus pada masalah (rencana, tindakan). Untuk yang di luar kendali: fokus pada emosi (menenangkan diri, menerima, mencari dukungan). Sering keduanya dipakai bersama.",hint:"Berfokus masalah & emosi sesuai situasi, atau satu cara / hanya ditahan?"},
{n:34,type:"mcq",micro:"Manajemen waktu & stres",q:"Mengelola waktu dengan lebih baik (merencanakan, memprioritaskan, tidak menunda hal penting) bisa mengurangi stres karena...",options:["Manajemen waktu tak berhubungan dengan stres, karena stres hanya dari tuntutan orang","Membuat hidup lebih kaku & menegangkan, sebab makin banyak rencana makin besar tekanan setiap hari","Mengurangi 'kejutan menit terakhir' & rasa selalu terburu-buru & tertinggal"],answer:2,explain:"Banyak stres pelajar berasal dari 'tugas yang menumpuk tak terkelola'. Perencanaan yang wajar (bukan jadwal super ketat) mengurangi tekanan itu.",hint:"Mengurangi kejutan & keterburuan, atau tak berhubungan / membuat kaku?"},
{n:35,type:"mcq",micro:"Menyeimbangkan tanggung jawab & istirahat",q:"Menjadwalkan waktu istirahat & kegiatan menyenangkan dengan sengaja (bukan hanya 'kalau sempat') penting saat periode menekan karena...",options:["Jeda yang terencana membantu tubuh & pikiran pulih, sehingga kita bisa menghadapi tanggung jawab dengan lebih baik, bukan kemalasan","Istirahat hanya diperlukan orang yang tidak serius dengan tanggung jawabnya, sehingga orang rajin sebaiknya tak menjadwalkan waktu bersantai","Makin sedikit istirahat makin banyak yang tercapai, sebab waktu istirahat mengurangi hasil pekerjaan kita sehari-hari"],answer:0,explain:"Jeda bukan 'lawan' produktivitas, tapi bagian dari bisa terus bekerja tanpa kelelahan. Menjadwalkannya membuatnya lebih mungkin terjadi.",hint:"Membantu pulih untuk menghadapi tanggung jawab, atau tanda tidak serius?"},
{n:36,type:"mcq",micro:"Stres & dukungan sosial",q:"Punya orang-orang yang bisa diandalkan (teman, keluarga, guru) berperan besar dalam menghadapi stres karena...",options:["Stres harus ditangani sendirian tanpa melibatkan orang lain, karena mereka tidak bisa membantu dan hanya menambah beban","Merasa didukung & tidak sendirian mengurangi beban stres, & orang lain bisa membantu dengan perspektif, bantuan praktis, atau sekadar mendengarkan","Bergantung pada orang lain adalah tanda kelemahan, sehingga orang kuat tidak butuh bantuan atau dukungan dari teman maupun keluarga"],answer:1,explain:"Manusia dirancang untuk saling mendukung. Punya & memakai jaringan dukungan adalah salah satu 'penyangga stres' terkuat.",hint:"Mengurangi beban & tidak sendirian, atau tanda lemah / harus sendiri?"},
{n:37,type:"tf",micro:"Stres tidak selalu terlihat dari luar",q:"Benar atau Salah: Kalau seseorang terlihat 'baik-baik saja' dari luar, kita bisa yakin ia pasti sedang tidak mengalami stres apa pun.",answer:false,explain:"Sebaliknya, banyak orang menyembunyikan stres berat di balik wajah tenang. Menanyakan kabar dengan tulus pada siapa pun, termasuk yang terlihat kuat, adalah kebaikan.",hint:"Bisa tersembunyi di balik 'baik-baik saja', atau selalu terlihat jelas?"},
{n:38,type:"mcq",micro:"Menerima ketidakpastian",q:"Untuk stres tentang hal yang belum pasti (hasil ujian, apakah pertemanan akan membaik), sikap yang membantu:",options:["Terus mengkhawatirkan hal yang belum terjadi tanpa henti setiap hari, karena dengan begitu kita siap menghadapi kemungkinan terburuk yang mungkin datang","Berpura-pura tidak peduli pada hasilnya, & menekan semua perasaan tentang hal itu supaya tidak terlihat gelisah di depan orang lain","Lakukan yang bisa kamu lakukan, lalu latih menerima bahwa sebagian hal memang belum bisa diketahui, & fokuskan energi pada hal-hal yang masih dalam kendalimu saat ini"],answer:2,explain:"Mengkhawatirkan hal yang belum bisa dikendalikan menguras energi tanpa mengubah hasilnya. Menerima ketidakpastian (sambil tetap bertindak) membebaskan energi untuk hal yang berguna.",hint:"Lakukan yang bisa + terima ketidakpastian, atau khawatir tanpa henti / berpura-pura tak peduli?"},
{n:39,type:"mcq",micro:"Stres & pikiran yang membesar-besarkan",q:"Saat stres, pikiran sering membesar-besarkan ('ini bencana total', 'aku pasti gagal & semua hancur'). Cara menyeimbangkannya:",options:["Periksa pikiran itu: apa bukti sebenarnya? apa kemungkinan yang lebih realistis? apa yang akan kukatakan pada teman yang berpikir begini?","Percaya pada pikiran terburuk yang muncul karena dianggap paling 'realistis', sehingga kita tak perlu memeriksa buktinya","Mengabaikan semua pikiran yang muncul, termasuk yang masuk akal, supaya kita tak terpengaruh oleh yang kita pikirkan saat tertekan"],answer:0,explain:"Stres 'mewarnai' pikiran jadi lebih gelap dari kenyataan. Memeriksanya membantu memisahkan 'yang terasa saat kalut' dari 'yang sebenarnya lebih mungkin'.",hint:"Periksa dengan bukti & alternatif, atau percaya terburuk / abaikan?"},
{n:40,type:"open",micro:"Analisis satu situasi stres",q:"Pilih satu situasi yang sedang atau baru saja membuatmu stres. Analisis: (a) situasinya & tanda-tanda stres yang kamu alami, (b) pisahkan bagian yang bisa kamu pengaruhi dari yang di luar kendalimu, (c) untuk bagian yang bisa kamu pengaruhi, satu langkah konkret & kecil, (d) untuk bagian yang di luar kendali, satu cara mengelola perasaanmu tentangnya, (e) satu sumber dukungan yang bisa kamu andalkan.",explain:"Jawaban baik: situasi & tanda stres yang spesifik, pemisahan yang jelas antara yang bisa & tidak bisa dikendalikan, satu langkah konkret & kecil untuk yang bisa dikendalikan (mengubah cemas jadi tindakan), satu cara mengelola perasaan untuk yang di luar kendali (bukan hanya 'menerima' tapi cara konkret), & sumber dukungan yang nyata.",hint:"Kunci: untuk yang bisa dikendalikan, ubah kecemasan jadi SATU tindakan kecil; untuk yang tidak, cari cara mengelola perasaan (menulis, mengingatkan diri, dukungan).",sample:"(a) Situasi: aku harus presentasi proyek kelompok minggu depan & anggota kelompokku belum menyelesaikan bagian mereka, aku takut hasilnya jelek & aku yang disalahkan. Tanda stres, aku susah tidur memikirkannya, perutku terasa mengganjal, & aku jadi sering mengecek grup chat berkali-kali dengan cemas. (b) Yang bisa kupengaruhi, bagianku sendiri (kupastikan selesai & rapi), cara aku berkomunikasi ke kelompok (aku bisa mengirim pesan yang jelas menanyakan progres & menawarkan bantuan), & persiapan presentasiku sendiri (aku bisa berlatih). Yang di luar kendaliku, apakah anggota lain benar-benar menyelesaikan bagian mereka tepat waktu, & bagaimana guru menilai. (c) Langkah konkret & kecil untuk yang bisa kupengaruhi, hari ini aku akan mengirim pesan ke grup, 'Teman-teman, presentasi tinggal seminggu, bisa update sampai mana bagian masing-masing? Kalau ada yang kesulitan, kita bisa bantu bareng besok pulang sekolah.' Ini langkah kecil yang mengubah rasa cemas jadi tindakan. (d) Mengelola perasaan untuk yang di luar kendali, aku akan mengingatkan diri bahwa aku sudah melakukan bagianku dengan baik & berkomunikasi dengan jelas; kalau hasilnya tetap kurang karena anggota lain, itu bukan sepenuhnya tanggung jawabku, & aku bisa menjelaskan kontribusiku pada guru bila perlu; aku juga akan menulis kekhawatiranku di buku catatan sebelum tidur supaya pikiranku tidak berputar. (e) Sumber dukungan, aku bisa bicara dengan kakakku yang pernah mengalami hal serupa, & bila situasinya benar-benar buruk & tidak adil, aku bisa bicara dengan wali kelas untuk meminta pendapat."},
{n:41,type:"mcq",micro:"Strategi berfokus pada masalah",q:"Contoh strategi 'berfokus pada masalah' untuk stres tugas:",options:["Menarik napas dalam, menenangkan diri dengan teknik relaksasi, & mencoba meredakan ketegangan","Membuat rencana belajar, memecah tugas jadi bagian kecil, meminta bantuan guru untuk materi sulit, mengatur waktu","Menonton video yang menghibur atau mendengarkan lagu favorit untuk mengalihkan pikiran dari tugas, sampai perasaan tertekan ringan"],answer:1,explain:"Strategi berfokus pada masalah mengubah atau menangani sumber stres itu sendiri. Cocok untuk hal yang bisa kita pengaruhi.",hint:"Rencana & tindakan pada sumbernya, atau mengalihkan pikiran / napas?"},
{n:42,type:"mcq",micro:"Strategi berfokus pada emosi",q:"Contoh strategi 'berfokus pada emosi' untuk stres:",options:["Membuat jadwal belajar yang rinci, memecah tugas besar jadi bagian kecil, & mengerjakannya sesuai prioritas","Meminta perpanjangan tenggat kepada guru, lalu merencanakan ulang pembagian tugas dan waktu supaya pekerjaan lebih mudah","Menarik napas, bergerak, menulis perasaan, berbicara dengan teman, melakukan hobi yang menenangkan"],answer:2,explain:"Strategi berfokus pada emosi membantu kita mengelola perasaan tentang stres. Cocok terutama untuk situasi di luar kendali kita, atau saat kita perlu tenang dulu sebelum bertindak.",hint:"Mengelola perasaan (napas, gerak, bicara, hobi), atau membuat jadwal / minta perpanjangan?"},
{n:43,type:"mcq",micro:"Kapan pakai strategi yang mana",q:"Untuk stres yang BISA kamu pengaruhi (tugas belum dikerjakan), pendekatan yang lebih tepat:",options:["Utamakan strategi berfokus pada masalah (rencana & tindakan), sambil memakai strategi emosi bila perlu menenangkan diri dulu","Hanya memakai strategi berfokus pada emosi seperti menenangkan diri, & mengabaikan tugasnya sampai perasaan tertekan hilang sendiri","Tidak melakukan apa-apa & menunggu stres berlalu sendiri, karena tugas yang belum selesai akan menyelesaikan dirinya nanti"],answer:0,explain:"Kalau kamu bisa mengubah situasinya, bertindak pada masalah biasanya paling melegakan. Menenangkan diri dulu bisa membantu jika kamu terlalu kewalahan untuk mulai.",hint:"Utamakan berfokus masalah + emosi bila perlu, atau hanya emosi / tidak apa-apa?"},
{n:44,type:"mcq",micro:"Kapan pakai strategi emosi",q:"Untuk stres yang di LUAR kendalimu (menunggu hasil ujian, cemas soal kesehatan keluarga), pendekatan yang lebih tepat:",options:["Mengabaikan perasaan sepenuhnya & berpura-pura tidak terjadi apa-apa, lalu menyibukkan diri dengan hal lain supaya tidak sempat memikirkan ketidakpastian itu","Utamakan strategi berfokus pada emosi (menenangkan diri, menerima ketidakpastian, mencari dukungan), karena tidak banyak yang bisa 'diperbaiki' saat ini","Terus mencoba 'menyelesaikan' hal yang memang tidak bisa kamu selesaikan, dengan memikirkannya berulang-ulang dan mencari cara mengendalikannya setiap hari"],answer:1,explain:"Menghabiskan energi mencoba mengendalikan yang tidak bisa dikendalikan menambah stres. Mengelola perasaan & mencari dukungan lebih membantu untuk situasi seperti ini.",hint:"Utamakan mengelola emosi & mencari dukungan, atau terus 'menyelesaikan' yang tak bisa / abaikan?"},
{n:45,type:"tf",micro:"Menulis mengurangi beban",q:"Benar atau Salah: Menuliskan hal-hal yang membebani pikiran tidak mungkin membantu & satu-satunya cara adalah memendam semuanya sendiri.",answer:false,explain:"Sebaliknya, 'memindahkan' isi kepala ke kertas memberi jarak & kejelasan, & membuat daftar tugas membantu memutus pikiran yang berputar terutama saat mau tidur.",hint:"Mengurangi beban & memperjelas, atau tak berpengaruh?"},
{n:46,type:"mcq",micro:"Grounding saat kewalahan",q:"Saat merasa sangat kewalahan & pikiran berputar cepat, teknik yang bisa membantu 'kembali membumi':",options:["Terus memikirkan semua masalah sekaligus tanpa berhenti, supaya tidak ada satu hal pun yang terlewatkan & kita merasa sudah siap menghadapi semuanya","Menahan napas selama mungkin sambil memejamkan mata rapat-rapat, lalu menghembuskannya dengan keras sampai semua pikiran yang berputar itu terdorong keluar","Grounding: sebutkan 5 hal yang kamu lihat, 4 yang didengar, 3 yang bisa disentuh, & seterusnya, membawa perhatian ke saat ini"],answer:2,explain:"Grounding mengalihkan perhatian dari 'badai pikiran' ke pengamatan konkret di sekitar, membantu menurunkan rasa kewalahan.",hint:"Grounding ke saat ini, atau pikirkan semua sekaligus / tahan napas?"},
{n:47,type:"mcq",micro:"Memecah tugas besar",q:"Menghadapi proyek/ujian besar yang terasa mustahil, langkah yang mengurangi rasa kewalahan:",options:["Pecah jadi tugas-tugas kecil yang spesifik ('baca bab 1', 'buat kerangka', 'kerjakan 10 soal'), lalu fokus pada satu tugas kecil pada satu waktu","Memikirkan seluruh proyek atau ujian itu sebagai satu beban raksasa yang harus diselesaikan sekaligus, supaya kita sadar betapa besar tantangan yang dihadapi","Menunggu sampai datang 'inspirasi' yang kuat untuk mengerjakan semuanya sekaligus, karena memulai tanpa semangat tidak menghasilkan apa-apa"],answer:0,explain:"'Bagaimana aku menyelesaikan semua ini?' terasa lumpuh. 'Apa satu langkah kecil berikutnya?' terasa bisa dilakukan.",hint:"Pecah jadi tugas kecil & fokus satu per satu, atau lihat sebagai beban raksasa?"},
{n:48,type:"mcq",micro:"Merawat tubuh saat stres",q:"Saat periode menekan, menjaga tidur, makan, & sedikit gerak...",options:["Tidak berpengaruh pada kemampuan kita menghadapi stres, karena kondisi tubuh dan pikiran tidak ada kaitannya dengan cara kita menghadapi tekanan","Lebih penting daripada biasanya, karena itulah yang membuat kita mampu menghadapi tekanan, meski godaan mengorbankannya besar","Sebaiknya dikorbankan demi memiliki lebih banyak waktu bekerja atau belajar, karena hasil yang besar hanya didapat oleh orang yang rela mengurangi istirahat"],answer:1,explain:"Godaan begadang & melewatkan makan saat stres tinggi sering justru menurunkan kemampuan menghadapinya. Fondasi harus dijaga terutama saat tekanan tinggi.",hint:"Lebih penting saat tekanan tinggi, atau dikorbankan untuk bekerja?"},
{n:49,type:"mcq",micro:"Aktivitas yang mengisi energi",q:"Menyisihkan waktu untuk kegiatan yang benar-benar kamu nikmati & yang mengisi energimu (hobi, waktu dengan orang yang disayangi, alam) saat stres...",options:["Membuang waktu saat banyak tugas, jadi kegiatan menyenangkan ditunda","Hanya boleh dilakukan setelah semua tugas selesai, karena bersenang-senang saat tugas menumpuk menunjukkan kita tidak bertanggung jawab","Bukan kemalasan, melainkan bagian dari merawat diri agar bisa terus menghadapi tuntutan"],answer:2,explain:"'Mengisi cangkir' dengan hal yang memberi energi membuat kita lebih mampu, bukan kurang. Menunggu 'semua selesai' sering berarti tidak pernah.",hint:"Bagian merawat diri, atau buang waktu / hanya setelah semua selesai?"},
{n:50,type:"order",micro:"Menyusun rencana menghadapi periode menekan",q:"Urutkan langkah menyusun rencana menghadapi periode menekan yang kamu tahu akan datang (mis. minggu ujian).",items:["Tuliskan semua yang perlu dikerjakan & tenggatnya","Pecah tugas besar jadi bagian kecil & jadwalkan dengan realistis (termasuk jeda & tidur)","Identifikasi bagian yang butuh bantuan & minta lebih awal, bukan menit terakhir","Jadwalkan juga waktu istirahat & kegiatan yang mengisi energi, bukan hanya kerja"],answer:[0,1,2,3],explain:"Tulis semua → pecah & jadwalkan realistis → minta bantuan lebih awal → jadwalkan juga istirahat. Rencana yang menyertakan istirahat lebih berkelanjutan.",hint:"Menjadwalkan waktu istirahat termasuk dalam rencana atau ditambahkan 'kalau sempat'?"},
{n:51,type:"mcq",micro:"Self-talk yang mendukung saat stres",q:"Contoh self-talk yang membantu (mengakui kesulitan sambil mendukung) saat stres:",options:["'Ini banyak & aku merasa kewalahan, tapi aku bisa mengerjakannya satu langkah demi langkah, & aku boleh minta bantuan'","'Ini gampang banget, nggak usah dipikirkan, beres sendiri' (padahal sebenarnya sedang menyangkal kesulitan yang ada)","'Aku akan gagal dalam hal ini, jadi percuma mencoba, lebih baik menyerah sebelum membuat kesalahan yang lebih besar'"],answer:0,explain:"Self-talk yang baik mengakui bahwa situasinya sulit (jujur) sambil menambahkan dukungan (aku bisa mencoba, aku boleh minta bantuan), bukan menyangkal atau menghancurkan.",hint:"Akui sulit + mendukung, atau menyangkal / menghancurkan?"},
{n:52,type:"tf",micro:"Meminta perpanjangan/bantuan itu sah",q:"Benar atau Salah: Kalau kamu benar-benar kewalahan, meminta perpanjangan tenggat, meminta bantuan guru/orang tua, atau menyesuaikan target adalah langkah yang sah & bertanggung jawab, bukan kegagalan.",answer:true,explain:"Mengenali batas & meminta penyesuaian saat benar-benar butuh adalah keterampilan mengelola diri yang matang, bukan tanda lemah.",hint:"Langkah sah & bertanggung jawab, atau kegagalan?"},
{n:53,type:"mcq",micro:"Stres & tenggat waktu",q:"Kalau kamu sering merasa terburu-buru & stres karena selalu mengerjakan segala sesuatu di menit terakhir, kebiasaan yang membantu:",options:["Menerima bahwa stres karena tenggat adalah hal normal bagi banyak orang, sehingga kebiasaan menunda tak perlu diubah","Mulai lebih awal (bahkan 15-20 menit) & mengerjakan sedikit demi sedikit, sehingga tidak ada 'kejutan besar' di akhir","Terus menunda sampai menit terakhir dengan prinsip 'aku kerja lebih baik di bawah tekanan', walau hasilnya sering tergesa-gesa dan membuat cemas"],answer:1,explain:"Mengerjakan lebih awal & bertahap mengurangi puncak stres di akhir. 'Aku kerja lebih baik di bawah tekanan' sering sebenarnya 'aku baru mulai karena panik'.",hint:"Mulai lebih awal & bertahap, atau terus menunda / terima stres tenggat?"},
{n:54,type:"mcq",micro:"Membedakan tekanan wajar & berlebihan",q:"Kalau tuntutan (jadwal, tugas, ekspektasi) benar-benar melebihi apa yang mungkin ditangani siapa pun dalam kondisimu, langkah yang bijak:",options:["Anggap itu 'salahmu' karena kurang mampu, lalu tanggung semuanya sendirian tanpa memberi tahu orang lain bahwa bebanmu terlalu berat","Menyerah pada semuanya sekaligus dengan berhenti mengerjakan tugas, tanpa bicara kepada orang lain tentang apa yang membuatmu kewalahan","Bicarakan dengan orang dewasa (orang tua, guru, wali kelas) tentang penyesuaian yang mungkin, bukan hanya memaksakan diri sampai kewalahan"],answer:2,explain:"Kadang masalahnya bukan kemampuan kita, tapi tuntutan yang memang tidak realistis. Itu layak dibicarakan, bukan ditanggung diam-diam.",hint:"Bicarakan penyesuaian dengan orang dewasa, atau salahkan diri / menyerah?"},
{n:55,type:"mcq",micro:"Stres & rutinitas menenangkan",q:"Membangun rutinitas kecil yang menenangkan (mis. teh hangat & musik pelan setelah belajar, jalan singkat, journaling sebelum tidur) berguna saat periode menekan karena...",options:["Memberi 'jangkar' teratur yang menurunkan ketegangan sebelum menumpuk terlalu besar","Membuat hari terlalu terjadwal dan kaku, sehingga kita kehilangan kebebasan & makin tertekan oleh banyak aturan kecil","Tidak bermanfaat, karena ketegangan hilang sendiri tanpa perlu kebiasaan teratur setiap harinya"],answer:0,explain:"Titik-titik pemulihan yang teratur sepanjang hari mencegah stres menumpuk sampai kewalahan.",hint:"Jangkar teratur menurunkan ketegangan, atau terlalu terjadwal / tak bermanfaat?"},
{n:56,type:"tf",micro:"Menghadapi stres bertahap",q:"Benar atau Salah: Untuk hal yang membuat stres & cenderung kamu hindari, memaksakan menghadapi semuanya sekaligus dalam satu waktu selalu jadi cara terbaik.",answer:false,explain:"Sebaliknya, penghindaran total membuat stres menumpuk & menghadapi sekaligus bisa terlalu berat; pendekatan bertahap dengan dukungan bila perlu membangun rasa mampu.",hint:"Bertahap dengan dukungan, atau menghindar total / sekaligus?"},
{n:57,type:"mcq",micro:"Mendukung teman yang stres",q:"Cara mendukung teman yang sedang stres:",options:["Menambah kekhawatiran mereka dengan ikut panik & membayangkan hal-hal terburuk yang mungkin terjadi, supaya mereka tahu bahwa kamu serius memperhatikan masalahnya","Dengarkan tanpa meremehkan, tanyakan apa yang mereka butuhkan (didengar? bantuan praktis? diajak keluar sebentar?), & ingatkan bahwa mereka tidak sendirian","Menyuruh mereka 'santai aja' & 'jangan berlebihan' karena masalahnya tidak sebesar itu, supaya mereka cepat tenang dan berhenti memikirkannya terus-menerus"],answer:1,explain:"Dukungan yang tidak meremehkan & menanyakan kebutuhan lebih membantu daripada nasihat menggampangkan atau ikut panik.",hint:"Dengarkan & tanya kebutuhan, atau menyuruh 'santai' / ikut panik?"},
{n:58,type:"mcq",micro:"Jeda mikro di tengah hari",q:"'Jeda mikro' (1-2 menit napas, peregangan, atau melihat ke luar jendela) di antara aktivitas menekan berguna karena...",options:["Membuang waktu produktif yang seharusnya dipakai menyelesaikan pekerjaan, sebab jeda memecah fokus","Hanya berguna kalau waktunya lebih dari 30 menit, sebab jeda yang lebih singkat tak cukup memengaruhi tubuh","Memberi tubuh & pikiran 'reset' kecil yang mencegah ketegangan menumpuk sepanjang hari"],answer:2,explain:"Jeda pendek yang sering bisa sama bergunanya dengan jeda panjang yang jarang, & lebih mudah disisipkan dalam jadwal padat.",hint:"Reset kecil mencegah ketegangan menumpuk, atau buang waktu / harus panjang?"},
{n:59,type:"mcq",micro:"Menghargai kemajuan kecil",q:"Saat menghadapi tugas atau periode yang besar & menekan, mengakui setiap langkah kecil yang selesai ('oke, satu bab beres') berguna karena...",options:["Menumbuhkan rasa 'aku sedang bergerak maju', yang mengurangi rasa kewalahan & menjaga motivasi","Membuat kita cepat puas dan malas melanjutkan, sebab mengakui hasil kecil terasa seperti pekerjaan sudah selesai","Tidak berpengaruh pada perasaan atau motivasi, karena hanya hasil akhir yang penting, bukan langkah kecil di tengah jalan"],answer:0,explain:"Fokus pada 'apa yang sudah kulakukan' (bukan hanya 'betapa banyak yang tersisa') membantu menjaga semangat di tengah tugas besar.",hint:"Rasa bergerak maju & menjaga motivasi, atau cepat puas / tak berpengaruh?"},
{n:60,type:"open",micro:"Rancang 'kotak alat anti-stres' pribadi",q:"Buat 'kotak alat' pribadimu untuk menghadapi stres. Sertakan: (a) 2 strategi berfokus pada masalah (untuk stres yang bisa kamu pengaruhi), (b) 2 strategi berfokus pada emosi (untuk menenangkan diri atau stres di luar kendali), (c) 2 kebiasaan 'penyangga' harian yang membuatmu lebih tahan stres, (d) 1-2 orang dukungan & kapan kamu akan menghubungi mereka, (e) tanda-tanda bahwa stres sudah terlalu besar/lama & kamu perlu bicara ke orang dewasa/profesional.",explain:"Jawaban baik: 2 strategi berfokus pada masalah yang konkret (menulis & memisahkan kendali, minta bantuan lebih awal), 2 strategi berfokus pada emosi (teknik menenangkan tubuh, menyalurkan lewat gerak/menulis), 2 kebiasaan penyangga harian yang relevan, orang dukungan spesifik dengan kapan menghubungi, & daftar tanda-tanda yang konkret kapan perlu bicara ke orang dewasa/profesional (durasi, dampak fungsi, hilangnya minat, rasa putus asa) dengan rencana bicara ke siapa.",hint:"Bagian (e) yang paling penting untuk topik ini, buat tanda-tandanya konkret (berapa lama, seberapa mengganggu, hilangnya minat, rasa putus asa) & sertakan rencana bicara ke siapa.",sample:"(a) Strategi berfokus pada masalah: (1) Menuliskan semua yang membebani, memisahkan yang bisa & tidak bisa kupengaruhi, lalu memecah yang bisa jadi langkah kecil & menjadwalkannya. (2) Meminta bantuan lebih awal (guru untuk materi sulit, teman untuk kerja kelompok, orang tua untuk hal di luar kemampuanku), bukan menunggu menit terakhir. (b) Strategi berfokus pada emosi: (1) Napas perlahan (tarik 4, hembus 6) sebanyak 6-8 kali + grounding 5-4-3-2-1 saat merasa kewalahan atau pikiran berputar. (2) Jalan kaki 15-20 menit atau menulis bebas di buku catatan untuk 'mengeluarkan' perasaan & menjernihkan pikiran. (c) Kebiasaan penyangga harian: (1) Tidur cukup (target lampu mati jam 22.15 di hari sekolah). (2) Bergerak sedikit setiap hari & menyisihkan minimal 20-30 menit untuk kegiatan yang kunikmati (menggambar atau mengobrol dengan teman). (d) Orang dukungan: ibuku (untuk hal berat atau yang menyangkut keluarga, kapan pun aku merasa perlu) & sahabatku Riko (untuk cerita sehari-hari, biasanya saat kami jalan pulang bareng); aku akan menghubungi mereka lebih awal saat mulai merasa kewalahan, bukan menunggu sampai benar-benar tidak sanggup. (e) Tanda perlu bicara ke orang dewasa/profesional: kalau stres berat berlangsung lebih dari 2-3 minggu tanpa membaik meski aku sudah memakai strategi-strategi ini; kalau mengganggu tidur, makan, sekolah, atau hubunganku secara terus-menerus; kalau aku kehilangan minat pada hampir semua hal yang biasa kunikmati; kalau aku merasa sangat putus asa atau bahwa 'tidak ada jalan keluar'; atau kalau aku merasa stres ini benar-benar di luar kemampuanku untuk ditangani. Dalam kasus seperti itu aku akan bicara dengan orang tuaku & wali kelas, & terbuka bahwa aku mungkin butuh bicara dengan konselor sekolah. Ini bukan hal yang sebaiknya kutangani sendiri."},
{n:61,type:"mcq",micro:"Stres kronis & tubuh",q:"Stres yang berkepanjangan tanpa jeda cukup bisa memengaruhi tubuh dengan cara...",options:["Tidak ada efek fisik dari stres kronis, karena stres yang berlangsung lama hanya memengaruhi pikiran dan perasaan, bukan kesehatan tubuh","Membuat lebih mudah sakit, sulit tidur terus-menerus, sakit kepala/perut berulang, & lelah yang tidak hilang dengan istirahat biasa","Membuat tubuh menjadi lebih kuat & lebih tahan terhadap penyakit, sebab semakin sering tubuh menghadapi tekanan, semakin terlatih pula daya tahannya"],answer:1,explain:"Tubuh yang terus-menerus dalam mode siaga akhirnya kelelahan. Ini kenapa stres kronis layak mendapat perhatian & bantuan, bukan sekadar 'ditahan'.",hint:"Lebih mudah sakit & lelah terus, atau lebih kuat / tak ada efek?"},
{n:62,type:"mcq",micro:"Kapan bicara ke orang dewasa tentang stres",q:"Tanda-tanda bahwa stres perlu dibicarakan dengan orang dewasa tepercaya atau tenaga profesional:",options:["Merasa gugup sebelum ujian atau tampil dalam acara penting, namun perasaan itu mereda setelah kegiatannya selesai dan tidak mengganggu aktivitas lain, sehingga tidak perlu dibicarakan dengan orang dewasa tepercaya karena itu hal yang sangat biasa","Sesekali merasa kewalahan oleh banyak tugas lalu pulih kembali dalam beberapa jam setelah istirahat, makan, dan berbincang dengan keluarga, sehingga tak perlu menceritakannya kepada orang dewasa","Berlangsung lama tanpa membaik meski sudah dicoba, mengganggu tidur/makan/sekolah/hubungan terus-menerus, kehilangan minat pada hampir semua hal, merasa putus asa, atau terasa benar-benar di luar kemampuan menanganinya sendiri"],answer:2,explain:"Stres akut yang mereda adalah bagian hidup. Stres yang menetap, mengganggu banyak hal, atau disertai rasa putus asa adalah tanda untuk mencari dukungan, bukan sesuatu yang harus dihadapi sendirian.",hint:"Menetap, mengganggu banyak hal, hilangnya minat, putus asa, atau gugup sesekali sebelum ujian?"},
{n:63,type:"tf",micro:"Meminta bantuan untuk stres bukan tanda lemah",q:"Benar atau Salah: Mencari bantuan (orang dewasa tepercaya, konselor, profesional) untuk stres yang terasa terlalu berat adalah langkah berani & bijak, bukan tanda kelemahan atau kegagalan.",answer:true,explain:"Sama seperti tubuh yang sakit butuh perhatian, pikiran & perasaan yang terbebani berat juga layak mendapat dukungan. Meminta bantuan adalah kekuatan.",hint:"Langkah berani & bijak, atau tanda lemah?"},
{n:64,type:"tf",micro:"Beberapa stres tidak boleh ditanggung sendiri",q:"Benar atau Salah: Beberapa jenis stres, misalnya yang menyangkut keselamatan, situasi keluarga yang berat, perundungan yang berlanjut, atau perasaan yang sangat gelap, memang perlu melibatkan orang dewasa & tidak seharusnya ditanggung sendirian oleh anak/remaja.",answer:true,explain:"Ada situasi yang di luar kapasitas siapa pun untuk ditangani sendirian, apalagi anak/remaja. Melibatkan orang dewasa yang tepat adalah langkah yang benar & bertanggung jawab.",hint:"Perlu melibatkan orang dewasa, atau harus ditanggung sendiri?"},
{n:65,type:"mcq",micro:"Stres & tekanan sebaya",q:"Kalau tekanan dari teman-teman (untuk bersaing, tampil sempurna, ikut yang tidak nyaman) menambah stresmu, sikap yang menjaga dirimu:",options:["Ingat bahwa kamu tidak harus memenuhi setiap ekspektasi orang lain; kamu boleh memilih apa yang sehat untukmu, meski berbeda dari kelompok","Mengikuti kemauan mereka agar diterima di dalam kelompok, walaupun hal itu membuatmu tak nyaman & menambah beban pikiran","Menghadapinya sendirian tanpa bercerita kepada orang lain, karena membicarakan tekanan teman membuatmu terlihat lemah dan dikucilkan"],answer:0,explain:"Sebagian besar tekanan sebaya adalah tentang 'apa yang kamu bayangkan mereka harapkan'. Menetapkan batas yang sehat, & bicara dengan orang tepercaya, membantu.",hint:"Boleh memilih yang sehat untukmu, atau selalu ikut / hadapi sendiri?"},
{n:66,type:"mcq",micro:"Stres & ekspektasi berlebihan dari luar",q:"Kalau kamu merasa terus-menerus stres karena takut mengecewakan orang tua/guru dengan nilai atau pencapaian, langkah yang sehat:",options:["Menyerah dan menuruti semua tuntutan mereka tanpa pernah menyampaikan keberatan, supaya mereka tidak kecewa & kamu tidak perlu membicarakan hal yang sulit, walaupun kamu sendiri merasa sangat tertekan","Bicarakan perasaanmu dengan mereka dengan jujur ('aku merasa sangat tertekan soal ini'), & bersama cari harapan yang lebih seimbang; mereka sering tidak menyadari beratnya tekanan yang kamu rasakan","Terus memaksakan diri diam-diam tanpa memberi tahu orang lain sampai akhirnya kewalahan, karena mengaku tertekan dianggap tanda gagal, dan itu dianggap tanda anak yang baik"],answer:1,explain:"Orang dewasa yang menyayangi kita sering tidak sadar seberapa berat tekanan yang kita rasakan. Percakapan jujur bisa membuka jalan ke harapan yang lebih sehat.",hint:"Bicarakan dengan jujur & cari harapan seimbang, atau memaksakan diam / menyerah?"},
{n:67,type:"mcq",micro:"Ketahanan (resiliensi)",q:"'Ketahanan' menghadapi stres & kesulitan bukan berarti tidak pernah terpukul, melainkan...",options:["Tidak merasakan kesulitan dalam hidup, karena orang yang tangguh bisa menghindari semua hal yang menyakitkan atau menekan","Menghadapi segalanya sendirian tanpa bantuan, sebab orang yang tangguh tak memerlukan dukungan dari orang lain","Kemampuan untuk pulih, beradaptasi, & terus maju setelah menghadapi kesulitan, sering dengan dukungan orang lain"],answer:2,explain:"Ketahanan dibangun dari dukungan sosial, kebiasaan sehat, cara berpikir yang membantu, & pengalaman menghadapi & pulih dari kesulitan. Bukan soal 'kuat sendirian'.",hint:"Kemampuan pulih & maju dengan dukungan, atau tak pernah kesulitan / selalu sendirian?"},
{n:68,type:"tf",micro:"Ketahanan bisa dibangun",q:"Benar atau Salah: Ketahanan menghadapi stres adalah sifat tetap; orang yang sekarang mudah kewalahan akan selalu begitu & tidak bisa berubah.",answer:false,explain:"Sebaliknya, ketahanan bisa diperkuat lewat kebiasaan sehat, hubungan yang mendukung, & cara berpikir yang membantu. Tiap kali kita pulih dari kesulitan, 'otot ketahanan' bertambah.",hint:"Bisa diperkuat, atau sifat tetap?"},
{n:69,type:"mcq",micro:"Stres yang produktif vs melumpuhkan",q:"Perbedaan stres yang 'produktif' (membantu tampil baik) dengan yang 'melumpuhkan':",options:["Produktif: cukup untuk membuat waspada & fokus, lalu bisa ditenangkan. Melumpuhkan: sangat besar sampai sulit berpikir, bertindak, atau berfungsi","Keduanya sama saja & hanya berbeda nama, sehingga tidak perlu dibedakan karena semua stres akan memberi dampak yang persis sama bagi setiap orang","Stres melumpuhkan & tidak membantu orang mana pun, sehingga rasa gugup sebelum tampil akan membuat seseorang gagal dan tidak berfungsi"],answer:0,explain:"Sedikit gugup yang membuat lebih fokus berbeda dari kecemasan yang sangat besar sampai 'membeku'. Yang kedua butuh strategi menenangkan & kadang bantuan.",hint:"Cukup untuk fokus vs sangat besar sampai membeku, atau sama saja?"},
{n:70,type:"tf",micro:"Kesehatan fisik & mental saling terkait dalam stres",q:"Benar atau Salah: Merawat kebiasaan fisik (tidur, makan, gerak) & merawat kesejahteraan emosi adalah dua hal yang benar-benar terpisah & tidak saling memengaruhi saat menghadapi stres.",answer:false,explain:"Sebaliknya, keduanya saling mendukung: tubuh yang terawat membuat lebih mudah mengelola stres, & mengelola stres membuat lebih mudah menjaga kebiasaan fisik.",hint:"Saling terkait & mendukung, atau terpisah?"},
{n:71,type:"mcq",micro:"Menghindari perbandingan stres",q:"Melihat teman yang tampak 'santai' menghadapi hal yang membuatmu stres tidak berarti...",options:["Kamu harus berpura-pura santai juga supaya orang lain tidak mengira kamu lebih lemah dari mereka","Kamu harus merasa buruk atau menyembunyikan stresmu; setiap orang merasakan & mengelola stres berbeda, & yang terlihat dari luar tidak menunjukkan seluruh cerita","Kamu memang lemah, karena orang yang kuat tidak mudah merasa tertekan oleh hal-hal kecil dalam hidupnya, jadi sebaiknya kamu menyembunyikannya"],answer:1,explain:"Orang menyembunyikan stres dengan cara berbeda. Yang terlihat 'santai' mungkin sedang berjuang di dalam, atau punya konteks yang berbeda darimu.",hint:"Setiap orang berbeda & yang terlihat tak menunjukkan semua, atau kamu 'lemah' / harus pura-pura?"},
{n:72,type:"mcq",micro:"Stres & keputusan besar",q:"Membuat keputusan besar (pindah sekolah, mengakhiri kegiatan) saat sedang dalam stres puncak...",options:["Paling tepat dibuat saat itu juga karena 'dari hati' dan paling jujur, sehingga tidak perlu ditunda atau dipertimbangkan kembali","Harus dibuat secepat mungkin supaya masalah tidak menumpuk, karena menunda keputusan penting hanya akan menambah stres yang sedang kita rasakan saat ini","Sebaiknya ditunda sampai lebih tenang bila memungkinkan; stres kuat mempersempit cara berpikir & keputusan yang dibuat di puncak sering disesali"],answer:2,explain:"Memberi jeda ('aku putuskan nanti setelah lebih tenang') sering menghasilkan keputusan yang lebih baik untuk hal-hal besar.",hint:"Tunda sampai tenang, atau putuskan saat puncak?"},
{n:73,type:"mcq",micro:"Stres berkelanjutan & meminta penyesuaian",q:"Kalau beban (jadwal, tugas, kegiatan) yang kamu tanggung memang terlalu banyak untuk siapa pun secara berkelanjutan, langkah yang sehat:",options:["Bicarakan dengan orang tua & guru tentang mengurangi atau menyesuaikan beberapa hal; kadang solusinya adalah menata ulang beban, bukan hanya 'lebih kuat menghadapinya'","Terus memaksakan semuanya tetap dijalani & menyalahkan diri karena merasa kewalahan, sebab setiap orang seharusnya bisa menanggung beban sebanyak itu","Meninggalkan semua kegiatan sekaligus tanpa bicara kepada orang lain, supaya beban hilang seketika dan kita tak perlu menjelaskan alasannya"],answer:0,explain:"Kadang masalahnya bukan kemampuan mengelola stres, tapi beban yang memang berlebihan. Menata ulang beban dengan bantuan orang dewasa adalah solusi yang sah.",hint:"Bicarakan penyesuaian beban, atau paksakan & salahkan diri / tinggalkan tanpa bicara?"},
{n:74,type:"mcq",micro:"Stres & belas kasih pada diri",q:"Kalau kamu kesulitan menghadapi stres & merasa 'aku seharusnya bisa lebih kuat', sikap yang lebih membantu:",options:["Menyerah saja karena 'aku memang tidak bisa menghadapi stres', sebab orang yang sudah merasa kewalahan berarti memang tidak ditakdirkan untuk kuat","Perlakukan diri seperti teman yang sedang kesulitan, dengan pengertian; menghadapi stres itu sulit & kamu sedang belajar, & kamu boleh minta bantuan","Menghukum diri sendiri karena dianggap 'kurang tangguh', dengan terus mengkritik diri sampai kita merasa pantas untuk bisa melewati kesulitan itu"],answer:1,explain:"Kritik diri yang keras saat sudah stres justru menambah beban. Belas kasih pada diri (bukan menghindari tanggung jawab, tapi kebaikan) membantu kita pulih & terus mencoba.",hint:"Pengertian pada diri + boleh minta bantuan, atau menghukum diri / menyerah?"},
{n:75,type:"order",micro:"Menilai apakah stres butuh bantuan profesional",q:"Urutkan langkah menilai apakah stres yang kamu alami butuh dukungan lebih dari orang dewasa/profesional.",items:["Perhatikan apakah kamu sudah memakai strategi menghadapi stres secara konsisten (menenangkan diri, menata beban, mencari dukungan awal)","Perhatikan berapa lama stres berat ini berlangsung (beberapa hari? berminggu-minggu?)","Perhatikan apakah itu mengganggu tidur, makan, sekolah, hubungan, atau membuatmu kehilangan minat pada hampir semua hal","Bila berat, lama, mengganggu banyak hal, atau disertai rasa putus asa, bicarakan dengan orang dewasa tepercaya & terbuka soal butuh bantuan lebih"],answer:[0,1,2,3],explain:"Cek strategi yang sudah dicoba → durasi → dampak & hilangnya minat → bicara ke dewasa bila berat & lama. Menilai bertahap sebelum menyimpulkan perlu bantuan tambahan.",hint:"Berbicara ke orang dewasa dilakukan di awal atau setelah menilai durasi & dampak?"},
{n:76,type:"tf",micro:"Stres bisa dikelola & dilewati",q:"Benar atau Salah: Meski stres adalah pengalaman yang tidak nyaman & kadang berat, sebagian besar periode stres bisa dikelola & dilewati dengan strategi yang tepat & dukungan yang cukup, situasinya bukan tanpa harapan.",answer:true,explain:"Pesan penting: stres itu nyata & bisa berat, tapi ada banyak cara nyata untuk menghadapinya, & bantuan tersedia. Kamu tidak harus menghadapinya sendirian.",hint:"Bisa dikelola & dilewati dengan dukungan, atau tanpa harapan?"},
{n:77,type:"mcq",micro:"Stres & pertumbuhan",q:"Menghadapi & mengatasi kesulitan (dengan dukungan yang cukup) kadang...",options:["Hanya merugikan tanpa sisi positif, sehingga kesulitan sebaiknya dihindari sejauh mungkin supaya kita tidak terluka","Berarti kita seharusnya mencari stres sebanyak mungkin dalam hidup, karena hanya dengan banyak tekanan orang bisa kuat dan berhasil","Membantu kita belajar tentang diri sendiri, membangun ketahanan, & merasa lebih mampu menghadapi tantangan berikutnya"],answer:2,explain:"Ini BUKAN berarti stres berat itu 'baik' atau harus dicari. Tapi mengatasi kesulitan (bukan menghindarinya) bisa membangun kepercayaan diri & keterampilan, terutama saat kita tidak sendirian menghadapinya.",hint:"Bisa membangun ketahanan & pemahaman diri, atau hanya merugikan / harus dicari?"},
{n:78,type:"mcq",micro:"Menyeimbangkan menghadapi stres & menjalani hidup",q:"Kalau kamu jadi terlalu fokus 'harus mengelola stres dengan sempurna' sampai stres sendiri, sikap yang lebih sehat:",options:["Ingat bahwa mengelola stres adalah alat untuk hidup lebih baik, bukan ujian yang harus dilalui sempurna; 'cukup baik' & terus belajar sudah bagus","Menuntut kesempurnaan dalam mengelola stres & menghukum diri setiap kali merasa kewalahan, supaya kita terus terpacu untuk menjadi lebih baik lagi setiap hari","Menyerah pada upaya mengelola stres, karena kalau tidak bisa dilakukan dengan sempurna, lebih baik tidak dilakukan sejak awal"],answer:0,explain:"Perfeksionisme dalam mengelola stres bisa jadi sumber stres baru. Tujuannya hidup yang lebih baik, bukan nilai sempurna.",hint:"'Cukup baik' & terus belajar, atau menuntut sempurna / menyerah?"},
{n:79,type:"mcq",micro:"Stres & komunitas yang mendukung",q:"Lingkungan (keluarga, kelas, sekolah) di mana orang bisa jujur soal stres & saling mendukung cenderung...",options:["Tidak berbeda dari lingkungan yang menuntut orang 'kuat sendiri', karena akhirnya tiap orang menghadapi tekanannya masing-masing","Membuat semua anggotanya lebih cepat mendapat bantuan saat kesulitan & lebih tahan menghadapi tekanan bersama","Menjadi lemah & tidak produktif, sebab terlalu banyak waktu terbuang untuk membicarakan stres daripada mengerjakan hal penting"],answer:1,explain:"Budaya yang aman untuk jujur soal stres & mencari bantuan membangun komunitas yang lebih tangguh & peduli.",hint:"Lebih cepat mendapat bantuan & lebih tahan bersama, atau lemah / tak berbeda?"},
{n:80,type:"open",micro:"Membedakan stres yang bisa dikelola sendiri & yang butuh bantuan",q:"Jelaskan dengan kata-katamu sendiri: (a) apa perbedaan antara stres yang biasanya bisa dikelola dengan strategi sendiri (& akan mereda) dengan stres yang butuh dukungan lebih (orang dewasa/profesional), sebutkan minimal 3 pembeda, (b) kenapa penting tidak menghakimi diri atau orang lain saat butuh dukungan lebih untuk stres, (c) contoh kalimat yang bisa dipakai untuk memulai percakapan meminta bantuan ke orang dewasa tepercaya tentang stres yang terasa terlalu berat.",explain:"Jawaban baik: minimal 3 pembeda yang jelas & benar (durasi, dampak pada fungsi dasar, hilangnya minat/harapan, kemampuan mengelola sendiri), penjelasan yang menekankan bahwa mencari bantuan adalah keberanian bukan kelemahan (analogi dengan sakit fisik membantu), & contoh kalimat pembuka yang konkret, jujur, & bisa benar-benar diucapkan.",hint:"Pembeda utamanya: berapa LAMA, seberapa mengganggu HAL-HAL DASAR, apakah masih bisa MENIKMATI hal biasa & merasa 'ini akan berlalu', & apakah strategi sendiri sudah tidak cukup.",sample:"(a) Perbedaan: (1) DURASI, stres yang bisa dikelola sendiri biasanya terkait situasi tertentu (ujian, konflik) & mereda setelah situasi itu lewat atau setelah beberapa hari; stres yang butuh dukungan lebih berlangsung berminggu-minggu tanpa membaik meski strategi sudah dicoba. (2) DAMPAK PADA FUNGSI, stres biasa mungkin mengganggu sebentar tapi kita masih bisa tidur, makan, mengikuti sekolah, & menikmati hal yang biasa; stres yang lebih berat mengganggu hal-hal dasar itu secara terus-menerus. (3) HILANGNYA MINAT & HARAPAN, dalam stres biasa kita masih bisa menikmati sebagian hal & merasa 'ini akan berlalu'; stres yang lebih berat membuat hampir semua hal terasa hambar & kadang muncul perasaan putus asa atau 'tidak ada jalan keluar'. (4) KEMAMPUAN MENGELOLA SENDIRI, stres biasa bisa kita hadapi dengan menenangkan diri, menata beban, & bicara dengan teman; stres yang lebih berat terasa benar-benar di luar kemampuan kita meski sudah mencoba semua itu. (b) Kenapa tidak menghakimi: karena butuh dukungan lebih bukan tanda lemah atau gagal, sama seperti tubuh yang sakit butuh dokter, pikiran & perasaan yang terbebani berat juga layak mendapat bantuan yang tepat; menghakimi (diri sendiri atau orang lain) hanya menambah beban & membuat orang malu untuk mencari bantuan padahal itu langkah berani. (c) Contoh kalimat memulai percakapan: 'Bu/Pak, aku ingin cerita sesuatu yang berat buatku. Belakangan ini aku merasa sangat tertekan dan kewalahan, sampai aku susah tidur, susah fokus di sekolah, dan rasanya nggak hilang-hilang meskipun aku sudah coba mengatasinya. Aku merasa ini di luar kemampuanku untuk hadapi sendiri. Boleh aku minta bantuan untuk memikirkan apa yang bisa kulakukan?'"},
{n:81,type:"mcq",micro:"Skenario: minggu ujian yang menumpuk",q:"Kamu punya 5 ujian dalam seminggu & merasa sangat kewalahan sampai sulit mulai belajar apa pun. Langkah pertama yang membantu:",options:["Belajar semua materi sekaligus dalam satu malam panjang tanpa istirahat, supaya semua ujian bisa terkejar dan kita tidak perlu memikirkannya lagi di hari berikutnya","Menghindari belajar karena terlalu kewalahan, dan berharap perasaan itu mereda sendiri menjelang hari ujian tanpa membuat rencana","Tenangkan diri sebentar (napas), tuliskan semua materi tiap ujian, pecah jadi bagian kecil, & buat jadwal realistis (termasuk jeda & tidur), lalu mulai dari satu bagian kecil"],answer:2,explain:"Rasa kewalahan sering berkurang begitu 'gunung' tugas dipecah jadi 'langkah-langkah'. Jadwal realistis yang menyertakan istirahat menjaga daya tahan.",hint:"Tenangkan + pecah + jadwalkan + mulai kecil, atau semua sekaligus / hindari?"},
{n:82,type:"mcq",micro:"Skenario: stres dari media sosial",q:"Kamu merasa lebih stres & buruk tentang dirimu setelah menghabiskan waktu di media sosial melihat pencapaian & kehidupan teman-teman. Langkah yang menjaga dirimu:",options:["Kurangi waktu di platform yang memicu perbandingan itu, ingatkan diri bahwa itu 'sorotan terbaik' bukan kehidupan utuh, & isi waktu dengan hal yang benar-benar memberi energi","Terus melihat lebih banyak unggahan mereka supaya kita terbiasa dan tidak lagi merasa tertekan, karena semakin sering dilihat perasaan itu akan semakin hilang dengan sendirinya","Menyimpulkan bahwa hidupmu memang kurang baik dibanding orang lain & merasa buruk tentang dirimu, lalu berusaha keras meniru kehidupan yang mereka tampilkan"],answer:0,explain:"Perbandingan dengan citra yang dikurasi hampir selalu merugikan. Mengurangi pemicunya & mengingat konteksnya (ini bukan gambaran lengkap) membantu.",hint:"Kurangi pemicu & ingat konteksnya, atau terus lihat / merasa buruk?"},
{n:83,type:"mcq",micro:"Skenario: konflik keluarga yang menekan",q:"Ada ketegangan berkelanjutan di rumah yang membuatmu stres & sulit fokus. Ini di luar kendalimu sepenuhnya. Langkah yang sehat:",options:["Berusaha 'memperbaiki' semua masalah keluarga itu sendirian, dengan menjadi penengah dalam setiap ketegangan sampai kamu sendiri kehabisan tenaga dan waktu, walaupun tidak ada seorang pun yang memintamu melakukannya","Fokus pada yang bisa kamu kendalikan (rutinitasmu, cara meresponmu), cari ruang tenang & dukungan (teman, keluarga besar, guru/konselor), & bicarakan dengan orang dewasa tepercaya bila terasa terlalu berat","Menyimpan semuanya sendiri & menganggapnya 'bukan urusanku untuk cerita', sebab masalah keluarga harus dirahasiakan dari orang di luar rumah, termasuk dari guru, konselor, dan teman"],answer:1,explain:"Stres dari situasi keluarga yang berat sering di luar kapasitas anak/remaja untuk selesaikan sendiri. Mencari dukungan & bicara dengan orang dewasa tepercaya adalah langkah yang benar.",hint:"Fokus yang bisa dikendalikan + cari dukungan + bicara ke dewasa, atau pendam / perbaiki sendiri?"},
{n:84,type:"mcq",micro:"Skenario: teman terlihat sangat stres & menarik diri",q:"Temanmu belakangan terlihat sangat stres, menarik diri, & bilang 'aku nggak sanggup lagi' berulang kali. Sikap yang tepat:",options:["Bilang 'ah, banyak orang juga stres kok' & mengganti topik, supaya dia tidak merasa masalahnya lebih besar daripada yang dialami orang lain, lalu berharap ia berhenti membahasnya","Menyimpan sendiri kekhawatiranmu tanpa memberi tahu orang lain, karena takut dianggap berlebihan atau mencampuri urusan pribadinya","Dengarkan dengan serius tanpa meremehkan, tunjukkan kamu peduli, & dorong dia bicara dengan orang dewasa tepercaya (& bila kamu sangat khawatir, beri tahu orang dewasa sendiri)"],answer:2,explain:"Ungkapan seperti 'aku nggak sanggup lagi' yang berulang perlu ditanggapi serius. Sebagai teman, kamu bisa mendukung & mendorong ke bantuan, tapi keselamatannya lebih penting daripada menjaga rahasia bila kamu sangat khawatir.",hint:"Dengarkan serius + dorong ke bantuan + beri tahu dewasa bila sangat khawatir, atau meremehkan / diam?"},
{n:85,type:"tf",micro:"Menghadapi stres adalah keterampilan hidup",q:"Benar atau Salah: Kemampuan menghadapi stres hanya berguna saat masih sekolah & tidak lagi relevan setelah dewasa & bekerja.",answer:false,explain:"Sebaliknya, stres akan selalu ada dalam bentuk berbeda sepanjang hidup. Belajar menghadapinya dengan sehat sekarang mendukung kesejahteraan, prestasi, & hubungan seumur hidup.",hint:"Keterampilan hidup penting yang luas, atau hanya soal sekolah?"},
{n:86,type:"mcq",micro:"Skenario: stres membuat pikiran membesar-besarkan",q:"Menjelang wawancara/audisi penting, pikiranmu terus berkata 'aku pasti gagal & mempermalukan diri'. Cara menyikapinya:",options:["Kenali bahwa ini pikiran yang diwarnai stres, periksa buktinya ('apakah aku selalu gagal? bukan'), ganti dengan pikiran yang lebih adil ('aku gugup, itu wajar, & aku sudah bersiap'), & tenangkan tubuh","Percaya sepenuhnya pada pikiran itu & langsung membatalkan wawancara atau audisinya, karena kalau sudah merasa akan gagal, tidak ada gunanya mencoba, lalu menghindari kesempatan serupa","Memaksa diri 'berpikir positif' dengan menyangkal bahwa kamu sedang gugup, lalu berpura-pura tidak merasakan apa-apa di dalam dirimu, sampai tubuhmu makin tegang saat tampil"],answer:0,explain:"Stres membuat pikiran lebih gelap dari kenyataan. Memeriksanya & mengganti dengan yang lebih seimbang (tetap jujur bahwa ini menantang) membantu.",hint:"Kenali, periksa, ganti dengan yang adil, tenangkan tubuh, atau percaya & batalkan / menyangkal gugup?"},
{n:87,type:"mcq",micro:"Skenario: tekanan untuk selalu sibuk & berprestasi",q:"Kamu merasa harus terus sibuk & berprestasi di semua bidang (akademik, ekstrakurikuler, sosial) sampai tidak pernah punya waktu istirahat & selalu lelah. Langkah yang sehat:",options:["Menerima bahwa kelelahan adalah 'harga yang harus dibayar untuk kesuksesan', sehingga tidak perlu mengubah jadwal atau mengurangi kegiatan","Tinjau prioritasmu, pertimbangkan mengurangi beberapa hal, jadwalkan waktu istirahat dengan sengaja, & bicarakan dengan orang tua bila mereka juga mendorong beban yang berlebihan","Terus menambah kegiatan baru supaya 'tidak ketinggalan' dari teman-temanmu, walaupun waktu istirahatmu sudah hampir tidak ada lagi dalam sehari-hari, bahkan di akhir pekan"],answer:1,explain:"Beban yang terus-menerus melebihi kapasitas tanpa jeda tidak berkelanjutan & bukan tanda kesuksesan. Menata ulang prioritas & menjadwalkan istirahat adalah keputusan dewasa.",hint:"Tinjau prioritas + jadwalkan istirahat + bicarakan, atau tambah kegiatan / terima kelelahan?"},
{n:88,type:"mcq",micro:"Skenario: stres yang tidak membaik meski sudah dicoba",q:"Selama sebulan kamu merasa sangat tertekan, sudah mencoba menenangkan diri, menata beban, & bicara dengan teman, tapi tidak membaik & mulai sulit tidur & fokus terus-menerus. Langkah yang bijak:",options:["Terus mencoba strategi yang sama sendirian sampai berhasil, berapa lama pun waktunya, tanpa memberi tahu orang lain betapa beratnya tekanan yang kamu rasakan","Menyimpulkan 'aku memang tidak bisa mengelola stres' lalu menyerah dan berhenti mencari bantuan, karena merasa semua cara sudah dicoba","Bicarakan dengan orang tua & wali kelas, & terbuka bahwa kamu mungkin butuh bicara dengan konselor sekolah; stres yang menetap meski sudah dicoba butuh dukungan lebih"],answer:2,explain:"Mengenali kapan stres lebih besar dari yang bisa ditangani sendiri, & mencari bantuan yang tepat, adalah bagian dari mengelola stres dengan bijak, bukan kegagalan.",hint:"Bicarakan & cari bantuan lebih, atau terus sendiri / menyerah?"},
{n:89,type:"mcq",micro:"Skenario: menyeimbangkan menghadapi stres & bersenang-senang",q:"Ada acara yang kamu nantikan malam ini, tapi kamu punya banyak tugas & merasa 'nggak pantas' bersenang-senang. Sikap yang seimbang:",options:["Kerjakan sebagian tugas dulu dengan fokus, lalu izinkan dirimu menikmati acara sebagai jeda yang kamu butuhkan; istirahat & kesenangan adalah bagian dari mengelola stres, bukan 'kemalasan'","Membatalkan acaranya & terus mengerjakan tugas sambil merasa tertekan, karena bersenang-senang saat tugas belum selesai berarti kita tidak bertanggung jawab, dan itu harus dihindari sepenuhnya","Pergi ke acara itu sambil terus merasa bersalah & tidak bisa menikmati apa-apa, karena pikiranmu penuh tugas yang belum selesai, lalu pulang lebih awal tanpa bicara"],answer:0,explain:"Menyelesaikan sebagian tugas lalu memberi diri jeda yang berkualitas lebih berkelanjutan daripada bekerja terus tanpa henti sambil tertekan. Kesenangan yang terencana adalah bagian merawat diri.",hint:"Kerjakan sebagian + izinkan menikmati acara sebagai jeda, atau batalkan / pergi sambil bersalah?"},
{n:90,type:"order",micro:"Proyek: membangun ketahanan stres dalam sebulan",q:"Urutkan langkah proyek 'membangun ketahanan menghadapi stres dalam sebulan'.",items:["Minggu 1: kenali pola stresmu, tanda-tanda awal, sumber utama, & apa yang biasanya kamu lakukan (sehat & kurang sehat)","Minggu 2: perkuat 1-2 kebiasaan 'penyangga' (tidur, gerak, dukungan sosial) & latih 1 teknik menenangkan diri saat tenang","Minggu 3: latih menerapkan strategi (berfokus masalah untuk yang bisa dikendalikan, berfokus emosi untuk yang tidak) pada situasi stres nyata","Minggu 4: tinjau, apa yang membantu? apa yang perlu disesuaikan? & pastikan kamu tahu kapan & ke siapa mencari bantuan bila stres terlalu berat"],answer:[0,1,2,3],explain:"Kenali pola → perkuat penyangga & latih teknik → terapkan strategi → tinjau & pastikan tahu kapan cari bantuan. Membangun fondasi sebelum menerapkan, diakhiri dengan kesadaran akan batas.",hint:"Memastikan tahu kapan & ke siapa cari bantuan ditempatkan di awal atau di akhir proyek?"},
{n:91,type:"mcq",micro:"Skenario: stres membuat kamu ingin menyerah pada sesuatu yang berarti",q:"Kegiatan yang kamu sukai (mis. klub debat, tim olahraga) belakangan terasa sangat menekan & kamu ingin berhenti sepenuhnya. Langkah yang matang sebelum memutuskan:",options:["Terus memaksakan diri bertahan meski sangat menderita, tanpa mengubah apa-apa, karena berhenti di tengah jalan berarti menyerah dan gagal, dan tekanan itu akan hilang sendiri kalau dipaksakan","Tenangkan diri, tunggu sampai stres puncak mereda, & pertimbangkan: apakah masalahnya kegiatannya sendiri, atau beban lain yang menumpuk? bisakah beban dikurangi atau jadwal disesuaikan sebelum memutuskan berhenti total?","Berhenti hari ini juga selagi sangat stres & penuh emosi, tanpa memikirkan penyebab sebenarnya, supaya tekanan langsung hilang, dan tak perlu membicarakannya dengan orang tua, pelatih, atau teman satu tim"],answer:1,explain:"Keputusan besar (berhenti dari hal yang berarti) sebaiknya tidak dibuat di puncak stres. Kadang solusinya menata ulang beban, bukan berhenti; kadang berhenti memang tepat, tapi diputuskan setelah tenang.",hint:"Tenangkan + tunggu + pertimbangkan menata ulang beban, atau berhenti saat puncak / terus menderita?"},
{n:92,type:"tf",micro:"Stres tidak menentukan seluruh kemampuanmu",q:"Benar atau Salah: Merasa stres & kesulitan menghadapi suatu periode tidak berarti kamu 'tidak mampu' atau 'lemah'; itu berarti kamu sedang menghadapi banyak tuntutan, & mencari cara & dukungan untuk menghadapinya adalah hal yang bijak.",answer:true,explain:"Stres adalah tentang keseimbangan antara tuntutan & sumber daya saat itu, bukan tentang nilai atau kemampuan seseorang secara keseluruhan.",hint:"Tidak menentukan kemampuanmu secara keseluruhan, atau berarti kamu lemah?"},
{n:93,type:"mcq",micro:"Skenario: menjadi teladan menghadapi stres",q:"Adik/sepupu yang lebih muda mengamati bagaimana kamu menghadapi stres. Cara menjadi teladan yang baik:",options:["Berpura-pura tidak merasa stres di depan mereka, supaya mereka mengira orang yang lebih besar tenang dan tak pernah kesulitan","Meledak atau panik di depan mereka lalu menyuruh mereka 'jangan seperti kakak', tanpa pernah menjelaskan apa yang terjadi atau bagaimana cara menanganinya, dan menganggap hal itu sudah cukup sebagai pelajaran penting bagi mereka","Tunjukkan secara terbuka: 'Aku lagi stres nih, aku mau bikin daftar & tarik napas dulu' atau 'aku cerita ke kakak/orang tua soal ini', menunjukkan bahwa stres wajar & ada cara sehat menghadapinya termasuk mencari bantuan"],answer:2,explain:"Anak belajar menghadapi stres dari melihat orang di sekitar mereka melakukannya secara sehat & terbuka, termasuk melihat bahwa mencari bantuan itu normal.",hint:"Tunjukkan cara sehat secara terbuka, atau pura-pura tak stres / meledak?"},
{n:94,type:"mcq",micro:"Skenario: transisi ke jenjang sekolah baru",q:"Kamu akan pindah ke jenjang sekolah baru (mis. SMP ke SMA) & merasa cemas soal semuanya, teman baru, pelajaran lebih berat, lingkungan asing. Cara menghadapinya:",options:["Akui bahwa cemas menghadapi perubahan besar itu wajar & sementara, lakukan yang bisa kamu siapkan (mengenal lingkungan bila memungkinkan, membicarakannya dengan orang yang pernah mengalaminya), & beri dirimu waktu untuk menyesuaikan diri","Berharap kecemasan hilang sendiri tanpa persiapan, sehingga cukup menunggu sampai hari pertama sekolah lalu melihat yang terjadi, tanpa mengenal lingkungan baru atau bicara dengan orang yang pernah mengalaminya","Menganggap rasa cemas berarti kamu 'tidak siap' & tak akan berhasil di sekolah baru, sehingga lebih baik menghindari perubahan itu, dan menunda mendaftar sampai rasa cemas hilang sepenuhnya"],answer:0,explain:"Stres saat transisi adalah normal & biasanya mereda setelah beberapa minggu penyesuaian. Persiapan yang bisa dilakukan + kesabaran pada diri membantu.",hint:"Akui wajar + siapkan yang bisa + beri waktu menyesuaikan, atau berharap hilang / anggap tak akan berhasil?"},
{n:95,type:"tf",micro:"Ada harapan & bantuan tersedia",q:"Benar atau Salah: Meski stres bisa terasa sangat berat & kadang membuat merasa terjebak, ada banyak cara nyata untuk menghadapinya & berbagai bentuk dukungan yang tersedia, situasinya bukan tanpa harapan.",answer:true,explain:"Pesan yang penting: stres itu nyata & bisa berat, tapi bisa dikelola & dilewati, & kamu tidak harus menghadapinya sendirian.",hint:"Ada cara & dukungan tersedia, atau tanpa harapan?"},
{n:96,type:"mcq",micro:"Skenario: menyeimbangkan strategi & penerimaan",q:"Kamu sudah melakukan semua yang bisa kamu lakukan untuk sebuah situasi menekan, tapi hasilnya masih belum jelas & kamu tetap cemas. Sikap yang sehat:",options:["Menyalahkan diri sendiri karena masih merasa cemas meski sudah berusaha, & menganggap itu tanda bahwa usaha yang kamu lakukan sebenarnya belum cukup baik, lalu memaksa diri berusaha lebih keras lagi","Akui bahwa kamu sudah melakukan bagianmu, latih menerima ketidakpastian yang tersisa, alihkan sebagian energi ke hal lain yang masih dalam kendalimu, & cari dukungan bila kecemasannya berat","Terus mencoba mengendalikan hal yang tidak bisa kamu kendalikan, dengan memikirkannya berulang-ulang setiap hari sampai hasilnya jelas, walaupun kamu sudah sangat kelelahan"],answer:1,explain:"Setelah melakukan yang bisa dilakukan, mengelola kecemasan yang tersisa (menerima ketidakpastian, mengalihkan energi, mencari dukungan) lebih membantu daripada terus mencoba mengendalikan yang tidak bisa dikendalikan.",hint:"Akui sudah berbuat + terima ketidakpastian + alihkan energi + cari dukungan, atau terus mengendalikan yang tak bisa / salahkan diri?"},
{n:97,type:"mcq",micro:"Menilai pemahaman diri",q:"Tanda kamu sudah cukup memahami cara menghadapi stres:",options:["Kamu hafal daftar teknik mengatasi stres dengan lengkap, tetapi tidak memakainya saat sendiri sedang tertekan, dan tidak mencari bantuan orang lain meski sudah sangat kewalahan","Kamu berusaha agar tidak merasakan stres dalam hidup, dengan menghindari tantangan dan hal baru yang sulit, serta menolak bantuan yang ditawarkan orang lain","Kamu bisa mengenali tanda stres pada diri, membedakan yang bisa & tidak bisa dikendalikan, punya strategi yang cocok untuk keduanya, merawat kebiasaan penyangga, & tahu kapan & ke siapa mencari bantuan"],answer:2,explain:"Keterampilan sejati: kenali tanda + bedakan kendali + strategi yang cocok + kebiasaan penyangga + tahu kapan cari bantuan. Bukan hafalan atau menghindari stres sama sekali.",hint:"Kenali + bedakan kendali + strategi + penyangga + tahu batas, atau hafal tanpa pakai / hindari stres?"},
{n:98,type:"mcq",micro:"Stres & masyarakat",q:"Lingkungan yang mengurangi stres yang tidak perlu (jadwal yang masuk akal, ekspektasi yang seimbang, budaya yang mendukung & tidak menuntut 'sempurna atau gagal') cenderung...",options:["Membuat semua anggotanya lebih sehat secara fisik & emosi & lebih mampu berkembang","Membuat orang malas & tidak berprestasi, sebab tanpa tekanan besar orang tak terdorong berusaha","Tidak berpengaruh pada kesejahteraan individu, karena stres hanya ditentukan sifat pribadi, bukan keadaan di sekitarnya"],answer:0,explain:"Lingkungan yang seimbang tidak berarti tanpa tantangan, tapi tantangan yang wajar & dukungan yang cukup, yang membuat orang bisa tumbuh tanpa kewalahan terus-menerus.",hint:"Lebih sehat & mampu berkembang, atau malas / tak berpengaruh?"},
{n:99,type:"mcq",micro:"Inti keterampilan",q:"Inti dari 'menghadapi stres & tekanan':",options:["Menyerah pada hal yang membuat stres dengan cara menghindarinya sepenuhnya, supaya kita tak lagi merasakan tekanan atau kewalahan, sehingga tak perlu mengenali tanda stres, menenangkan diri, ataupun meminta bantuan dari orang dewasa tepercaya","Kenali tanda stres, tenangkan tubuh & pikiran, bedakan yang bisa & tidak bisa kamu kendalikan, pakai strategi yang cocok (berfokus masalah / emosi), rawat kebiasaan penyangga & dukungan sosial, & tahu kapan & ke siapa mencari bantuan bila stres terlalu berat atau lama","Berusaha agar tidak merasakan stres & menahan semuanya sendirian, karena meminta bantuan dianggap kelemahan yang harus dihindari, sehingga kita tak perlu membedakan hal yang bisa dikendalikan, memilih strategi, ataupun menjaga dukungan sosial"],answer:1,explain:"Kenali + tenangkan + bedakan kendali + strategi yang cocok + penyangga & dukungan + tahu kapan cari bantuan. Stres adalah bagian hidup yang bisa dikelola, bukan dikalahkan sendirian atau dihindari sepenuhnya.",hint:"Kenali + tenangkan + bedakan + strategi + dukungan + tahu batas, atau tak pernah stres / menyerah?"},
{n:100,type:"open",micro:"Kapstone: rencana menghadapi stres pribadi",q:"Tulis rencana lengkap menghadapi stres pribadimu untuk dipegang seterusnya. Sertakan: (a) tanda-tanda awal stres yang akan kamu waspadai (fisik, emosi, pikiran, perilaku), (b) langkah pertama saat menyadari stres memuncak, (c) strategi berfokus pada masalah & berfokus pada emosi yang cocok untukmu, (d) kebiasaan 'penyangga' harian & daftar dukungan sosial, (e) tanda-tanda & rencana konkret kapan kamu akan bicara ke orang dewasa/profesional, (f) bagaimana kamu akan bersikap pada diri sendiri saat kesulitan menghadapi stres.",explain:"Jawaban baik: tanda awal stres yang spesifik untuk keempat area (fisik, emosi, pikiran, perilaku), langkah pertama yang jelas (akui + tenangkan tubuh + jeda), strategi berfokus masalah & emosi yang konkret & cocok, kebiasaan penyangga & dukungan sosial spesifik dengan kapan menghubungi, daftar tanda & rencana konkret kapan bicara ke orang dewasa/profesional (durasi, dampak fungsi, hilangnya minat, rasa putus asa), & sikap pada diri saat kesulitan yang menggabungkan pengertian + penyesuaian realistis + kesediaan minta bantuan tanpa malu.",hint:"Bagian (e) & (f) yang paling penting untuk topik ini, buat kriteria kapan cari bantuan sangat konkret, & sikap pada diri harus menggabungkan pengertian dengan kesediaan mencari bantuan.",sample:"(a) Tanda awal stres: fisik, sakit kepala sore hari, bahu & rahang tegang, susah tidur; emosi, mudah kesal & cemas, merasa kewalahan; pikiran, sulit fokus, pikiran melompat ke banyak hal, membesar-besarkan ('ini bencana'); perilaku, menunda-nunda, mudah marah pada keluarga, lebih banyak mengecek HP dengan cemas. (b) Langkah pertama saat memuncak: berhenti sejenak & akui 'aku sedang stres, tubuhku bereaksi'; tarik napas perlahan (tarik 4, hembus 6) sebanyak 6-8 kali; kalau bisa, jauhkan diri sebentar dari pemicunya. (c) Strategi: BERFOKUS MASALAH (untuk yang bisa kupengaruhi), tuliskan semua yang membebani, pisahkan yang bisa & tidak bisa kukendalikan, pecah yang bisa jadi langkah kecil & jadwalkan, minta bantuan lebih awal. BERFOKUS EMOSI (untuk menenangkan atau yang di luar kendali), jalan kaki 15-20 menit atau menulis bebas; grounding 5-4-3-2-1; mengingatkan diri bahwa emosi kuat seperti gelombang & akan mereda; menerima ketidakpastian setelah melakukan yang bisa kulakukan. (d) Kebiasaan penyangga harian, tidur cukup (lampu mati jam 22.15 hari sekolah), bergerak sedikit setiap hari, makan teratur, & menyisihkan 20-30 menit untuk hal yang kunikmati. Dukungan sosial, ibuku (hal berat & keluarga, kapan pun perlu), sahabatku (cerita sehari-hari, saat jalan pulang), wali kelas (hal sekolah). Aku akan menghubungi mereka lebih awal saat mulai kewalahan, bukan menunggu tidak sanggup. (e) Tanda & rencana cari bantuan lebih, aku akan bicara ke orang tua & wali kelas (& terbuka soal butuh konselor) bila, stres berat berlangsung lebih dari 2-3 minggu tanpa membaik meski strategi sudah kupakai; mengganggu tidur/makan/sekolah/hubungan terus-menerus; aku kehilangan minat pada hampir semua hal yang biasa kunikmati; muncul perasaan sangat putus asa atau 'tidak ada jalan keluar'; atau stres terasa benar-benar di luar kemampuanku menanganinya. Ini bukan hal yang sebaiknya kutangani sendiri. (f) Sikap pada diri saat kesulitan, aku akan mengingatkan diri bahwa menghadapi stres itu sulit & aku sedang belajar, & bahwa merasa stres tidak berarti aku lemah, hanya berarti aku sedang menghadapi banyak tuntutan; aku akan memperlakukan diriku seperti teman yang sedang kesulitan (dengan pengertian, bukan kritik keras), menyesuaikan target agar realistis daripada menyerah, & mengizinkan diri meminta bantuan tanpa merasa malu."},
];
